insert into public.rulesets (id, created_by, slug, name, edition, source, description, status) values
  ('1d8b3e11-e6f0-52ec-baac-d710fbbdddd6', null, 'dnd-srd-5-2-1', 'D&D SRD 5.2.1 (2024 rules)', '5.2.1', 'https://www.dndbeyond.com/srd', 'D&D System Reference Document 5.2.1, Copyright Wizards of the Coast LLC. Licensed under CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Source: https://www.dndbeyond.com/srd. Changes: extracted, normalized, and structured as catalog records.', 'published')
insert into public.classes (id, ruleset_id, created_by, slug, name, description, hit_die, primary_abilities, saving_throw_proficiencies, proficiencies, starting_equipment, status) values
  ('1a16065b-6561-5d69-93dd-d5450c2d94c7', '1d8b3e11-e6f0-52ec-baac-d710fbbdddd6', null, 'barbarian', 'Barbarian', '', '12', array['Strength']::text[], array['Strength', 'Constitution']::text[], '{"skill_choice_count":2,"skill_options":["Animal Handling","Athletics","Intimidation","Nature","Perception","Survival"],"weapon_proficiencies":"Simple and Martial weapons","tool_proficiencies":"","armor_training":"Light and Medium armor and Shields"}'::jsonb, '{"description":"Choose A or B: (A) Greataxe, 4 Handaxes, Explorer’s Pack, and 15 GP; or (B) 75 GP"}'::jsonb, 'published'),
  ('22b20d48-0de7-5cfe-9331-2abb539eb964', '1d8b3e11-e6f0-52ec-baac-d710fbbdddd6', null, 'bard', 'Bard', '', '8', array['Charisma']::text[], array['Dexterity', 'Charisma']::text[], '{"skill_choice_count":3,"skill_options":["Acrobatics","Animal Handling","Arcana","Athletics","Deception","History","Insight","Intimidation","Investigation","Medicine","Nature","Perception","Performance","Persuasion","Religion","Sleight of Hand","Stealth","Survival"],"weapon_proficiencies":"Simple weapons","tool_proficiencies":"Choose 3 Musical Instruments (see “Equipment”)","armor_training":"Light armor"}'::jsonb, '{"description":"Choose A or B: (A) Leather Armor, 2 Daggers, Musical Instrument of your choice, Entertainer’s Pack, and 19 GP; or (B) 90 GP"}'::jsonb, 'published'),
  ('34c849dc-dfc7-5f9c-b77f-ad342fffda2f', '1d8b3e11-e6f0-52ec-baac-d710fbbdddd6', null, 'cleric', 'Cleric', '', '8', array['Wisdom']::text[], array['Wisdom', 'Charisma']::text[], '{"skill_choice_count":2,"skill_options":["History","Insight","Medicine","Persuasion","Religion"],"weapon_proficiencies":"Simple weapons","tool_proficiencies":"","armor_training":"Light and Medium armor and Shields"}'::jsonb, '{"description":"Choose A or B: (A) Chain Shirt, Shield, Mace, Holy Symbol, Priest’s Pack, and 7 GP; or (B) 110 GP"}'::jsonb, 'published'),
  ('b449f0f1-b0b6-5b91-b48f-bc85e88ab800', '1d8b3e11-e6f0-52ec-baac-d710fbbdddd6', null, 'druid', 'Druid', '', '8', array['Wisdom']::text[], array['Intelligence', 'Wisdom']::text[], '{"skill_choice_count":2,"skill_options":["Animal Handling","Arcana","Insight","Medicine","Nature","Perception","Religion","Survival"],"weapon_proficiencies":"Simple weapons","tool_proficiencies":"Herbalism Kit","armor_training":"Light armor and Shields"}'::jsonb, '{"description":"Choose A or B: (A) Leather Armor, Shield, Sickle, Druidic Focus (Quarterstaff), Explorer’s Pack, Herbalism Kit, and 9 GP; or (B) 50 GP"}'::jsonb, 'published'),
  ('6b143f9f-d5f3-53a8-8719-02a16d3ea716', '1d8b3e11-e6f0-52ec-baac-d710fbbdddd6', null, 'fighter', 'Fighter', '', '10', array['Strength', 'Dexterity']::text[], array['Strength', 'Constitution']::text[], '{"skill_choice_count":2,"skill_options":["Acrobatics","Animal Handling","Athletics","History","Insight","Intimidation","Perception","Persuasion","Survival"],"weapon_proficiencies":"Simple and Martial weapons","tool_proficiencies":"","armor_training":"Light, Medium, and Heavy armor and Shields"}'::jsonb, '{"description":"Choose A, B, or C: (A) Chain Mail, Greatsword, Flail, 8 Javelins, Dungeoneer’s Pack, and 4 GP; (B) Studded Leather Armor, Scimitar, Short sword, Longbow, 20 Arrows, Quiver, Dungeoneer’s Pack, and 11 GP; or (C) 155 GP"}'::jsonb, 'published'),
  ('a7e680c3-1793-5de4-9a33-af770518e180', '1d8b3e11-e6f0-52ec-baac-d710fbbdddd6', null, 'monk', 'Monk', '', '8', array['Dexterity', 'Wisdom']::text[], array['Strength', 'Dexterity']::text[], '{"skill_choice_count":2,"skill_options":["Acrobatics","Athletics","History","Insight","Religion","Stealth"],"weapon_proficiencies":"Simple weapons and Martial weapons that have the Light property","tool_proficiencies":"Choose one type of Artisan’s Tools or Musical Instrument (see “Equipment”)","armor_training":"None"}'::jsonb, '{"description":"Choose A or B: (A) Spear, 5 Daggers, Artisan’s Tools or Musical Instrument chosen for the tool proficiency above, Explorer’s Pack, and 11 GP; or (B) 50 GP"}'::jsonb, 'published'),
  ('785e1ced-5060-5378-81be-8ee97b6ca952', '1d8b3e11-e6f0-52ec-baac-d710fbbdddd6', null, 'paladin', 'Paladin', '', '10', array['Strength', 'Charisma']::text[], array['Wisdom', 'Charisma']::text[], '{"skill_choice_count":2,"skill_options":["Athletics","Insight","Intimidation","Medicine","Persuasion","Religion"],"weapon_proficiencies":"Simple and Martial weapons","tool_proficiencies":"","armor_training":"Light, Medium, and Heavy armor and Shields"}'::jsonb, '{"description":"Choose A or B: (A) Chain Mail, Shield, Longsword, 6 Javelins, Holy Symbol, Priest’s Pack, and 9 GP; or (B) 150 GP"}'::jsonb, 'published'),
  ('69774ce3-58ef-5243-8791-73bc57f5d780', '1d8b3e11-e6f0-52ec-baac-d710fbbdddd6', null, 'ranger', 'Ranger', '', '10', array['Dexterity', 'Wisdom']::text[], array['Strength', 'Dexterity']::text[], '{"skill_choice_count":3,"skill_options":["Animal Handling","Athletics","Insight","Investigation","Nature","Perception","Stealth","Survival"],"weapon_proficiencies":"Simple and Martial weapons","tool_proficiencies":"","armor_training":"Light and Medium armor and Shields"}'::jsonb, '{"description":"Choose A or B: (A) Studded Leather Armor, Scimitar, Shortsword, Longbow, 20 Arrows, Quiver, Druidic Focus (sprig of mistletoe), Explorer’s Pack, and 7 GP; or (B) 150 GP"}'::jsonb, 'published'),
  ('a9d07b8e-7a78-5e0d-8e09-4fb9fdaa9eed', '1d8b3e11-e6f0-52ec-baac-d710fbbdddd6', null, 'rogue', 'Rogue', '', '8', array['Dexterity']::text[], array['Dexterity', 'Intelligence']::text[], '{"skill_choice_count":4,"skill_options":["Acrobatics","Athletics","Deception","Insight","Intimidation","Investigation","Perception","Persuasion","Sleight of Hand","Stealth"],"weapon_proficiencies":"Simple weapons and Martial weapons that have the Finesse or Light property","tool_proficiencies":"Thieves’ Tools","armor_training":"Light armor"}'::jsonb, '{"description":"Choose A or B: (A) Leather Armor, 2 Daggers, Short sword, Shortbow, 20 Arrows, Quiver, Thieves’ Tools, Burglar’s Pack, and 8 GP; or (B) 100 GP"}'::jsonb, 'published'),
  ('dbf8d73e-f82f-58a7-a36a-2c3a1ddda08d', '1d8b3e11-e6f0-52ec-baac-d710fbbdddd6', null, 'sorcerer', 'Sorcerer', '', '6', array['Charisma']::text[], array['Constitution', 'Charisma']::text[], '{"skill_choice_count":2,"skill_options":["Arcana","Deception","Insight","Intimidation","Persuasion","Religion"],"weapon_proficiencies":"Simple weapons","tool_proficiencies":"","armor_training":"None"}'::jsonb, '{"description":"Choose A or B: (A) Spear, 2 Daggers, Arcane Focus (crystal), Dungeoneer’s Pack, and 28 GP; or (B) 50 GP"}'::jsonb, 'published'),
  ('e5b23717-e6b9-5d80-b72f-fa1814d2b63c', '1d8b3e11-e6f0-52ec-baac-d710fbbdddd6', null, 'warlock', 'Warlock', '', '8', array['Charisma']::text[], array['Wisdom', 'Charisma']::text[], '{"skill_choice_count":2,"skill_options":["Arcana","Deception","History","Intimidation","Investigation","Nature","Religion"],"weapon_proficiencies":"Simple weapons","tool_proficiencies":"","armor_training":"Light armor"}'::jsonb, '{"description":"Choose A or B: (A) Leather Armor, Sickle, 2 Daggers, Arcane Focus (orb), Book (occult lore), Scholar’s Pack, and 15 GP; or (B) 100 GP"}'::jsonb, 'published'),
  ('b5122a8b-bc17-5619-ac14-00e1b6306dbd', '1d8b3e11-e6f0-52ec-baac-d710fbbdddd6', null, 'wizard', 'Wizard', '', '6', array['Intelligence']::text[], array['Intelligence', 'Wisdom']::text[], '{"skill_choice_count":2,"skill_options":["Arcana","History","Insight","Investigation","Medicine","Nature","Religion"],"weapon_proficiencies":"Simple weapons","tool_proficiencies":"","armor_training":"None"}'::jsonb, '{"description":"Choose A or B: (A) 2 Daggers, Arcane Focus (Quarterstaff), Robe, Spellbook, Scholar’s Pack, and 5 GP; or (B) 55 GP"}'::jsonb, 'published')
insert into public.subclasses (id, class_id, created_by, slug, name, description, unlock_level, status) values
  ('2ef3e11a-b954-5660-8f98-88e778757ac0', '1a16065b-6561-5d69-93dd-d5450c2d94c7', null, 'path-of-the-berserker', 'Path of the Berserker', 'Barbarians who walk the Path of the Berserker direct their Rage primarily toward violence. Their path is one of untrammeled fury, and they thrill in the chaos of battle as they allow their Rage to seize and empower them.', '3', 'published'),
  ('2652e01b-5e7d-540d-a513-3af113b0632b', '22b20d48-0de7-5cfe-9331-2abb539eb964', null, 'college-of-lore', 'College of Lore', 'Bards of the College of Lore collect spells and secrets from diverse sources, such as scholarly tomes, mystical rites, and peasant tales. The college’s members gather in libraries and universities to share their lore with one another. They also meet at festivals or affairs of state, where they can expose corruption, unravel lies, and poke fun at self-important figures of authority.', '3', 'published'),
  ('c14a2ee6-343c-5812-bda8-63e0b30d72d5', '34c849dc-dfc7-5f9c-b77f-ad342fffda2f', null, 'life-domain', 'Life Domain', 'The Life Domain focuses on the positive energy that helps sustain all life in the multiverse. Clerics who tap into this domain are masters of healing, using that life force to cure many hurts. Existence itself relies on the positive energy associated with this domain, so a Cleric of almost any religious tradition might choose it. This domain is particularly associated with agricultural deities, gods of healing or endurance, and gods of home and community. Religious orders of healing also seek the magic of this domain.', '3', 'published'),
  ('4064c082-baf5-597d-8f3f-5fa3ced994aa', 'b449f0f1-b0b6-5b91-b48f-bc85e88ab800', null, 'circle-of-the-land', 'Circle of the Land', 'The Circle of the Land comprises mystics and sages who safeguard ancient knowledge and rites. These Druids meet within sacred circles of trees or standing stones to whisper primal secrets in Druidic. The circle’s wisest members preside as the chief priests of their communities.', '3', 'published'),
  ('4e77cc18-7c2c-5465-bf5d-f5c30dd5939d', '6b143f9f-d5f3-53a8-8719-02a16d3ea716', null, 'champion', 'Champion', 'A Champion focuses on the development of martial prowess in a relentless pursuit of victory. Champions combine rigorous training with physical excellence to deal devastating blows, withstand peril, and garner glory. Whether in athletic contests or bloody battle, Champions strive for the crown of the victor.', '3', 'published'),
  ('ec0244d7-3b5b-55f9-ab3b-11f9a16ce608', 'a7e680c3-1793-5de4-9a33-af770518e180', null, 'warrior-of-the-open-hand', 'Warrior of the Open Hand', 'Warriors of the Open Hand are masters of unarmed combat. They learn techniques to push and trip their opponents and manipulate their own energy to protect themselves from harm.', '3', 'published'),
  ('705c71cf-9a8b-5e5e-8d4a-0b561faecd3c', '785e1ced-5060-5378-81be-8ee97b6ca952', null, 'oath-of-devotion', 'Oath of Devotion', 'The Oath of Devotion binds Paladins to the ideals of justice and order. These Paladins meet the archetype of the knight in shining armor. They hold themselves to the highest standards of conduct, and some—for better or worse—hold the rest of the world to the same standards. Many who swear this oath are devoted to gods of law and good and use their gods’ tenets as the measure of personal devotion. Others hold angels as their ideals and incorporate images of angelic wings into their helmets or coats of arms. These paladins share the following tenets: • Let your word be your promise. • Protect the weak and never fear to act. • Let your honorable deeds be an example.', '3', 'published'),
  ('e0d69daf-a13f-5c45-a3cd-3c0cdb236a00', '69774ce3-58ef-5243-8791-73bc57f5d780', null, 'hunter', 'Hunter', 'You stalk prey in the wilds and elsewhere, using your abilities as a Hunter to protect nature and people everywhere from forces that would destroy them.', '3', 'published'),
  ('f6c6f0ca-7e54-5cc9-a2c4-c3a90dda6b11', 'a9d07b8e-7a78-5e0d-8e09-4fb9fdaa9eed', null, 'thief', 'Thief', 'A mix of burglar, treasure hunter, and explorer, you are the epitome of an adventurer. In addition to improving your agility and stealth, you gain abilities useful for delving into ruins and getting maximum benefit from the magic items you find there.', '3', 'published'),
  ('30728cae-bb3a-5f5e-9ecc-0e75d8998d33', 'dbf8d73e-f82f-58a7-a36a-2c3a1ddda08d', null, 'draconic-sorcery', 'Draconic Sorcery', 'Your innate magic comes from the gift of a dragon. Perhaps an ancient dragon facing death bequeathed some of its magical power to you or your ancestor. You might have absorbed magic from a site infused with dragons’ power. Or perhaps you handled a treasure taken from a dragon’s hoard that was steeped in draconic power. Or you might have a dragon for an ancestor.', '3', 'published'),
  ('2549fc10-701e-500d-8548-45e6e3c6af21', 'e5b23717-e6b9-5d80-b72f-fa1814d2b63c', null, 'fiend-patron', 'Fiend Patron', 'Your pact draws on the Lower Planes, the realms of perdition. You might forge a bargain with a demon lord, an archdevil, or another fiend that is especially mighty. That patron’s aims are evil—the corruption or destruction of all things, ultimately including you—and your path is defined by the extent to which you strive against those aims.', '3', 'published'),
  ('80fa2ec1-660b-5ad1-a105-950c676858c4', 'b5122a8b-bc17-5619-ac14-00e1b6306dbd', null, 'evoker', 'Evoker', 'Your studies focus on magic that creates powerful elemental effects such as bitter cold, searing flame, rolling thunder, crackling lightning, and burning acid. Some Evokers find employment in military forces, serving as artillery to blast armies from afar. Others use their power to protect others, while some seek their own gain.', '3', 'published')
insert into public.class_features (id, class_id, slug, name, description, level, sort_order, choices, prerequisites) values
  ('e8e4bdd6-26c0-571c-bba4-16d8b61df1bc', '1a16065b-6561-5d69-93dd-d5450c2d94c7', 'rage-level-1', 'Rage', 'You can imbue yourself with a primal power called Rage, a force that grants you extraordinary might and resilience. You can enter it as a Bonus Action if you aren’t wearing Heavy armor. You can enter your Rage the number of times shown for your Barbarian level in the Rages column of the Barbarian Features table. You regain one expended use when you finish a Short Rest, and you regain all expended uses when you finish a Long Rest.', '1', '0', '{}'::jsonb, '{}'::jsonb),
  ('da870a3d-3174-5479-8d6d-517f82a45623', '1a16065b-6561-5d69-93dd-d5450c2d94c7', 'unarmored-defense-level-1', 'Unarmored Defense', 'While you aren’t wearing any armor, your base Armor Class equals 10 plus your Dexterity and Constitution modifiers. You can use a Shield and still gain this benefit.', '1', '1', '{}'::jsonb, '{}'::jsonb),
  ('6422de3a-2f6e-54b3-b4b9-965dd9d389d7', '1a16065b-6561-5d69-93dd-d5450c2d94c7', 'weapon-mastery-level-1', 'Weapon Mastery', 'Your training with weapons allows you to use the mastery properties of two kinds of Simple or Martial Melee weapons of your choice, such as Greataxes and Handaxes. Whenever you finish a Long Rest, you can practice weapon drills and change one of those weapon choices. When you reach certain Barbarian levels, you gain the ability to use the mastery properties of more kinds of weapons, as shown in the Weapon Mastery column of the Barbarian Features table.', '1', '2', '{}'::jsonb, '{}'::jsonb),
  ('80794473-50d4-5ba4-b0a6-a674f495680c', '1a16065b-6561-5d69-93dd-d5450c2d94c7', 'danger-sense-level-2', 'Danger Sense', 'You gain an uncanny sense of when things aren’t as they should be, giving you an edge when you dodge perils. You have Advantage on Dexterity saving throws unless you have the Incapacitated condition.', '2', '3', '{}'::jsonb, '{}'::jsonb),
  ('ff1d9dd1-8a67-528d-aa8a-b218c50b8f26', '1a16065b-6561-5d69-93dd-d5450c2d94c7', 'reckless-attack-level-2', 'Reckless Attack', 'You can throw aside all concern for defense to attack with increased ferocity. When you make your first attack roll on your turn, you can decide to attack recklessly. Doing so gives you Advantage on attack rolls using Strength until the start of your next turn, but attack rolls against you have Advantage during that time. Level 3: Barbarian Subclass You gain a Barbarian subclass of your choice. The Path of the Berserker subclass is detailed after this class’s description. A subclass is a specialization that grants you features at certain Barbarian levels. For the rest of your career, you gain each of your subclass’s features that are of your Barbarian level or lower.', '2', '4', '{}'::jsonb, '{}'::jsonb),
  ('78ea35f4-2276-517d-a2ac-ca4b4b40da41', '1a16065b-6561-5d69-93dd-d5450c2d94c7', 'primal-knowledge-level-3', 'Primal Knowledge', 'You gain proficiency in another skill of your choice from the skill list available to Barbarians at level 1. In addition, while your Rage is active, you can channel primal power when you attempt certain tasks; whenever you make an ability check using one of the following skills, you can make it as a Strength check even if it normally uses a different ability: Acrobatics, Intimidation, Perception, Stealth, or Survival. When you use this ability, your Strength represents primal power coursing through you, honing your agility, bearing, and senses.', '3', '5', '{}'::jsonb, '{}'::jsonb),
  ('e2fced90-1a6e-5dd0-9f1f-af7dc09232e8', '1a16065b-6561-5d69-93dd-d5450c2d94c7', 'ability-score-improvement-level-4', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Barbarian levels 8, 12, and 16.', '4', '6', '{}'::jsonb, '{}'::jsonb),
  ('8328048c-bf6f-57e9-8ac0-8290210780f1', '1a16065b-6561-5d69-93dd-d5450c2d94c7', 'extra-attack-level-5', 'Extra Attack', 'You can attack twice instead of once whenever you take the Attack action on your turn.', '5', '7', '{}'::jsonb, '{}'::jsonb),
  ('cba41935-8daf-5634-8a0a-c88d7f2ef274', '1a16065b-6561-5d69-93dd-d5450c2d94c7', 'fast-movement-level-5', 'Fast Movement', 'Your speed increases by 10 feet while you aren’t wearing Heavy armor.', '5', '8', '{}'::jsonb, '{}'::jsonb),
  ('903e4c8f-fd70-534c-b2ec-d25e5fd51bdc', '1a16065b-6561-5d69-93dd-d5450c2d94c7', 'feral-instinct-level-7', 'Feral Instinct', 'Your instincts are so honed that you have Advantage on Initiative rolls.', '7', '9', '{}'::jsonb, '{}'::jsonb),
  ('b6748ff0-211c-5ae8-a230-cc8a9bd3190b', '1a16065b-6561-5d69-93dd-d5450c2d94c7', 'instinctive-pounce-level-7', 'Instinctive Pounce', 'As part of the Bonus Action you take to enter your Rage, you can move up to half your Speed.', '7', '10', '{}'::jsonb, '{}'::jsonb),
  ('a0489327-68f2-535c-9209-1433041e9e6c', '1a16065b-6561-5d69-93dd-d5450c2d94c7', 'ability-score-improvement-level-8', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Barbarian levels 8, 12, and 16.', '8', '11', '{}'::jsonb, '{}'::jsonb),
  ('058fd957-b9d1-5b6d-8148-c7e9ec828ec7', '1a16065b-6561-5d69-93dd-d5450c2d94c7', 'brutal-strike-level-9', 'Brutal Strike', 'If you use Reckless Attack, you can forgo any Advantage on one Strength-based attack roll of your choice on your turn. The chosen attack roll mustn’t have Disadvantage. If the chosen attack roll hits, the target takes an extra 1d10 damage of the same type dealt by the weapon or Unarmed Strike, and you can cause one Brutal Strike effect of your choice. You have the following effect options. Forceful Blow. The target is pushed 15 feet straight away from you. You can then move up to half your Speed straight toward the target without provoking Opportunity Attacks. Hamstring Blow. The target’s Speed is reduced by 15 feet until the start of your next turn. A target can be affected by only one Hamstring Blow at a time— the most recent one.', '9', '12', '{}'::jsonb, '{}'::jsonb),
  ('a0f607b9-f953-5e21-ae34-63f57536a1a2', '1a16065b-6561-5d69-93dd-d5450c2d94c7', 'relentless-rage-level-11', 'Relentless Rage', 'Your Rage can keep you fighting despite grievous wounds. If you drop to 0 Hit Points while your Rage is active and don’t die outright, you can make a DC 10 Constitution saving throw. If you succeed, your Hit Points instead change to a number equal to twice your Barbarian level. Each time you use this feature after the first, the DC increases by 5. When you finish a Short or Long Rest, the DC resets to 10.', '11', '13', '{}'::jsonb, '{}'::jsonb),
  ('c7b070b1-257e-566b-8151-137c931127c2', '1a16065b-6561-5d69-93dd-d5450c2d94c7', 'ability-score-improvement-level-12', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Barbarian levels 8, 12, and 16.', '12', '14', '{}'::jsonb, '{}'::jsonb),
  ('3547850a-4cdc-54b4-882c-2e9eb7304ba1', '1a16065b-6561-5d69-93dd-d5450c2d94c7', 'improved-brutal-strike-level-13', 'Improved Brutal Strike', 'You have honed new ways to attack furiously. The following effects are now among your Brutal Strike options. Staggering Blow. The target has Disadvantage on the next saving throw it makes, and it can’t make Opportunity Attacks until the start of your next turn. Sundering Blow. Before the start of your next turn, the next attack roll made by another creature against the target gains a +5 bonus to the roll. An attack roll can gain only one Sundering Blow bonus.', '13', '15', '{}'::jsonb, '{}'::jsonb),
  ('1eeeb413-c099-5ab5-820b-bcf1550d9594', '1a16065b-6561-5d69-93dd-d5450c2d94c7', 'persistent-rage-level-15', 'Persistent Rage', 'When you roll Initiative, you can regain all expended uses of Rage. After you regain uses of Rage in this way, you can’t do so again until you finish a Long Rest. In addition, your Rage is so fierce that it now lasts for 10 minutes without you needing to do anything to extend it from round to round. Your Rage ends early if you have the Unconscious condition (not just the Incapacitated condition) or don Heavy armor.', '15', '16', '{}'::jsonb, '{}'::jsonb),
  ('f404f7d1-537c-5d19-b4f4-3d6acc95beca', '1a16065b-6561-5d69-93dd-d5450c2d94c7', 'ability-score-improvement-level-16', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Barbarian levels 8, 12, and 16.', '16', '17', '{}'::jsonb, '{}'::jsonb),
  ('5af30899-d8cb-5760-80dd-bb7ec09cc4aa', '1a16065b-6561-5d69-93dd-d5450c2d94c7', 'improved-brutal-strike-level-17', 'Improved Brutal Strike', 'The extra damage of your Brutal Strike increases to 2d10. In addition, you can use two different Brutal Strike effects whenever you use your Brutal Strike feature.', '17', '18', '{}'::jsonb, '{}'::jsonb),
  ('5f50571d-a022-54cb-a44e-24a76fa1b9cc', '1a16065b-6561-5d69-93dd-d5450c2d94c7', 'indomitable-might-level-18', 'Indomitable Might', 'If your total for a Strength check or Strength saving throw is less than your Strength score, you can use that score in place of the total.', '18', '19', '{}'::jsonb, '{}'::jsonb),
  ('028462de-58db-5ec2-85fb-38fedc35a10b', '1a16065b-6561-5d69-93dd-d5450c2d94c7', 'epic-boon-level-19', 'Epic Boon', 'You gain an Epic Boon feat (see “Feats”) or another feat of your choice for which you qualify. Boon of Irresistible Offense is recommended.', '19', '20', '{}'::jsonb, '{}'::jsonb),
  ('feaa6efd-8b4d-5fc3-a8e0-c95803169206', '1a16065b-6561-5d69-93dd-d5450c2d94c7', 'primal-champion-level-20', 'Primal Champion', 'You embody primal power. Your Strength and Constitution scores increase by 4, to a maximum of 25.', '20', '21', '{}'::jsonb, '{}'::jsonb),
  ('10b45a31-e752-5ecb-b19f-a01ba341b349', '22b20d48-0de7-5cfe-9331-2abb539eb964', 'bardic-inspiration-level-1', 'Bardic Inspiration', 'You can supernaturally inspire others through words, music, or dance. This inspiration is represented by your Bardic Inspiration die, which is a d6. Using Bardic Inspiration. As a Bonus Action, you can inspire another creature within 60 feet of yourself who can see or hear you. That creature gains', '1', '0', '{}'::jsonb, '{}'::jsonb),
  ('326961dd-c5eb-5562-8252-a17a7f0f615c', '22b20d48-0de7-5cfe-9331-2abb539eb964', 'spellcasting-level-1', 'Spellcasting', 'You have learned to cast spells through your bardic arts. See “Spells” for the rules on spellcasting. The information below details how you use those rules with Bard spells, which appear in the Bard spell list later in the class’s description. Cantrips. You know two cantrips of your choice from the Bard spell list. Dancing Lights and Vicious Mockery are recommended. Whenever you gain a Bard level, you can replace one of your cantrips with another cantrip of your choice from the Bard spell list. When you reach Bard levels 4 and 10, you learn another cantrip of your choice from the Bard spell list, as shown in the Cantrips column of the Bard Features table. Spell Slots. The Bard Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you finish a Long Rest. Prepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose four level 1 spells from the Bard spell list. Charm Person , Color Spray, Dissonant Whispers, and Healing Word are recommended. The number of spells on your list increases as you gain Bard levels, as shown in the Prepared Spells column of the Bard Features table. Whenever that number increases, choose additional spells from the Bard spell list until the number of spells on your list matches the number on the table. The chosen spells must be of a level for which you have spell slots. For example, if you’re a level 3 Bard, your list of prepared spells can include six spells of levels 1 and 2 in any combination. If another Bard feature gives you spells that you always have prepared, those spells don’t count against the number of spells you can prepare with this feature, but those spells otherwise count as Bard spells for you. Changing Your Prepared Spells. Whenever you gain a Bard level, you can replace one spell on your list with another Bard spell for which you have spell slots. Spellcasting Ability. Charisma is your spellcasting ability for your Bard spells. Spellcasting Focus. You can use a Musical Instrument as a Spellcasting Focus for your Bard spells.', '1', '1', '{}'::jsonb, '{}'::jsonb),
  ('0f556b0a-be03-50e1-8f4c-3878851220a0', '22b20d48-0de7-5cfe-9331-2abb539eb964', 'expertise-level-2', 'Expertise', 'You gain Expertise (see “Rules Glossary”) in two of your skill proficiencies of your choice. Performance and Persuasion are recommended if you have proficiency in them. At Bard level 9, you gain Expertise in two more of your skill proficiencies of your choice.', '2', '2', '{}'::jsonb, '{}'::jsonb),
  ('19351353-4253-5f89-9862-db3c001807fa', '22b20d48-0de7-5cfe-9331-2abb539eb964', 'jack-of-all-trades-level-2', 'Jack of All Trades', 'You can add half your Proficiency Bonus (round down) to any ability check you make that uses a skill proficiency you lack and that doesn’t otherwise use your Proficiency Bonus. For example, if you make a Strength (Athletics) check and lack Athletics proficiency, you can add half your Proficiency Bonus to the check. Level 3: Bard Subclass You gain a Bard subclass of your choice. The College of Lore subclass is detailed after this class’s description. A subclass is a specialization that grants you features at certain Bard levels. For the rest of your career, you gain each of your subclass’s features that are of your Bard level or lower.', '2', '3', '{}'::jsonb, '{}'::jsonb),
  ('9ddde774-8566-5520-97e6-76c6caee6011', '22b20d48-0de7-5cfe-9331-2abb539eb964', 'ability-score-improvement-level-4', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Bard levels 8, 12, and 16.', '4', '4', '{}'::jsonb, '{}'::jsonb),
  ('bb0c7e05-212e-5212-be12-4636a8caf44c', '22b20d48-0de7-5cfe-9331-2abb539eb964', 'font-of-inspiration-level-5', 'Font of Inspiration', 'You now regain all your expended uses of Bardic Inspiration when you finish a Short or Long Rest. In addition, you can expend a spell slot (no action required) to regain one expended use of Bardic Inspiration.', '5', '5', '{}'::jsonb, '{}'::jsonb),
  ('5bb7a6f7-1a14-504b-bf46-103800ef9bcb', '22b20d48-0de7-5cfe-9331-2abb539eb964', 'countercharm-level-7', 'Countercharm', 'You can use musical notes or words of power to disrupt mind-influencing effects. If you or a creature within 30 feet of you fails a saving throw against an effect that applies the Charmed or Frightened condition, you can take a Reaction to cause the save to be rerolled, and the new roll has Advantage.', '7', '6', '{}'::jsonb, '{}'::jsonb),
  ('afc9f8b0-ea6e-5ebd-9e27-67ef0e223a63', '22b20d48-0de7-5cfe-9331-2abb539eb964', 'ability-score-improvement-level-8', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Bard levels 8, 12, and 16.', '8', '7', '{}'::jsonb, '{}'::jsonb),
  ('f32817e2-17b8-5b6b-80a5-2e803621182f', '22b20d48-0de7-5cfe-9331-2abb539eb964', 'magical-secrets-level-10', 'Magical Secrets', 'You’ve learned secrets from various magical traditions. Whenever you reach a Bard level (including this level) and the Prepared Spells number in the Bard Features table increases, you can choose any of your new prepared spells from the Bard, Cleric, Druid, and Wizard spell lists, and the chosen spells count as Bard spells for you (see a class’s section for its spell list). In addition, whenever you replace a spell prepared for this class, you can replace it with a spell from those lists.', '10', '8', '{}'::jsonb, '{}'::jsonb),
  ('ce3687c5-69ec-5856-8c5c-2a343edc0837', '22b20d48-0de7-5cfe-9331-2abb539eb964', 'ability-score-improvement-level-12', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Bard levels 8, 12, and 16.', '12', '9', '{}'::jsonb, '{}'::jsonb),
  ('369773da-ea8a-5920-b743-e39789636ee1', '22b20d48-0de7-5cfe-9331-2abb539eb964', 'ability-score-improvement-level-16', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Bard levels 8, 12, and 16.', '16', '10', '{}'::jsonb, '{}'::jsonb),
  ('0caa81e7-11dc-529c-80ec-29c3c8c6873b', '22b20d48-0de7-5cfe-9331-2abb539eb964', 'superior-inspiration-level-18', 'Superior Inspiration', 'When you roll Initiative, you regain expended uses of Bardic Inspiration until you have two if you have fewer than that.', '18', '11', '{}'::jsonb, '{}'::jsonb),
  ('93f9ad0c-af51-5436-a188-5894e832d14a', '22b20d48-0de7-5cfe-9331-2abb539eb964', 'epic-boon-level-19', 'Epic Boon', 'You gain an Epic Boon feat (see “Feats”) or another feat of your choice for which you qualify. Boon of Spell Recall is recommended.', '19', '12', '{}'::jsonb, '{}'::jsonb),
  ('4c00e99d-69cc-5563-abeb-ba51c8e5cb54', '22b20d48-0de7-5cfe-9331-2abb539eb964', 'words-of-creation-level-20', 'Words of Creation', 'You have mastered two of the Words of Creation: the words of life and death. You therefore always have the Power Word Heal and Power Word Kill spells prepared. When you cast either spell, you can target a second creature with it if that creature is within 10 feet of the first target.', '20', '13', '{}'::jsonb, '{}'::jsonb),
  ('28215ee2-8deb-5db6-ba1a-8170f0196660', '34c849dc-dfc7-5f9c-b77f-ad342fffda2f', 'spellcasting-level-1', 'Spellcasting', 'You have learned to cast spells through prayer and meditation. See “Spells” for the rules on spellcasting. The information below details how you use those rules with Cleric spells, which appear on the Cleric spell list later in the class’s description. Cantrips. You know three cantrips of your choice from the Cleric spell list. Guidance , Sacred Flame, and Thaumaturgy are recommended. Whenever you gain a Cleric level, you can replace one of your cantrips with another cantrip of your choice from the Cleric spell list.', '1', '0', '{}'::jsonb, '{}'::jsonb),
  ('f1c111e9-698f-560a-8816-7e83c1a0394e', '34c849dc-dfc7-5f9c-b77f-ad342fffda2f', 'divine-order-level-1', 'Divine Order', 'You have dedicated yourself to one of the following sacred roles of your choice. Protector. Trained for battle, you gain proficiency with Martial weapons and training with Heavy armor. Thaumaturge. You know one extra cantrip from the Cleric spell list. In addition, your mystical connection to the divine gives you a bonus to your Intelligence (Arcana or Religion) checks. The bonus equals your Wisdom modifier (minimum of +1).', '1', '1', '{}'::jsonb, '{}'::jsonb),
  ('7ca4e06e-f833-528d-8d3c-2b2ff2225fcd', '34c849dc-dfc7-5f9c-b77f-ad342fffda2f', 'channel-divinity-level-2', 'Channel Divinity', 'You can channel divine energy directly from the Outer Planes to fuel magical effects. You start with two such effects: Divine Spark and Turn Undead, each of which is described below. Each time you use this class’s Channel Divinity, choose which Channel Divinity effect from this class to create. You gain additional effect options at higher Cleric levels. You can use this class’s Channel Divinity twice. You regain one of its expended uses when you finish a Short Rest, and you regain all expended uses when you finish a Long Rest. You gain additional uses when you reach certain Cleric levels, as shown in the Channel Divinity column of the Cleric Features table. If a Channel Divinity effect requires a saving throw, the DC equals the spell save DC from this class’s Spellcasting feature. Divine Spark. As a Magic action, you point your Holy Symbol at another creature you can see within 30 feet of yourself and focus divine energy at it. Roll 1d8 and add your Wisdom modifier. You either restore Hit Points to the creature equal to that total or force the creature to make a Constitution saving throw. On a failed save, the creature takes Necrotic or Radiant damage (your choice) equal to that total. On a successful save, the creature takes half as much damage (round down). You roll an additional d8 when you reach Cleric levels 7 (2d8), 13 (3d8), and 18 (4d8). Turn Undead. As a Magic action, you present your Holy Symbol and censure Undead creatures. Each Undead of your choice within 30 feet of you must make a Wisdom saving throw. If the creature fails its save, it has the Frightened and Incapacitated conditions for 1 minute. For that duration, it tries to move as far from you as it can on its turns. This effect ends early on the creature if it takes any damage, if you have the Incapacitated condition, or if you die. Level 3: Cleric Subclass You gain a Cleric subclass of your choice. The Life Domain subclass is detailed after this class’s description. A subclass is a specialization that grants you features at certain Cleric levels. For the rest of your career, you gain each of your subclass’s features that are of your Cleric level or lower.', '2', '2', '{}'::jsonb, '{}'::jsonb),
  ('7c64a6fd-7d9f-5904-846c-7298ea2ba04c', '34c849dc-dfc7-5f9c-b77f-ad342fffda2f', 'ability-score-improvement-level-4', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Cleric levels 8, 12, and 16.', '4', '3', '{}'::jsonb, '{}'::jsonb),
  ('67173609-39f4-56d9-a055-e9e4e11768bb', '34c849dc-dfc7-5f9c-b77f-ad342fffda2f', 'sear-undead-level-5', 'Sear Undead', 'Whenever you use Turn Undead, you can roll a number of d8s equal to your Wisdom modifier (minimum of 1d8) and add the rolls together. Each Undead that fails its saving throw against that use of Turn Undead takes Radiant damage equal to the roll’s total. This damage doesn’t end the turn effect.', '5', '4', '{}'::jsonb, '{}'::jsonb),
  ('a753fc7f-ef8f-5801-8021-80ae97490985', '34c849dc-dfc7-5f9c-b77f-ad342fffda2f', 'blessed-strikes-level-7', 'Blessed Strikes', 'Divine power infuses you in battle. You gain one of the following options of your choice (if you get either option from a Cleric subclass in an older book, use only the option you choose for this feature). Divine Strike. Once on each of your turns when you hit a creature with an attack roll using a weapon, you can cause the target to take an extra 1d8 Necrotic or Radiant damage (your choice). Potent Spellcasting. Add your Wisdom modifier to the damage you deal with any Cleric cantrip.', '7', '5', '{}'::jsonb, '{}'::jsonb),
  ('024b7786-c5e3-5fdf-b41a-1136490cdf0c', '34c849dc-dfc7-5f9c-b77f-ad342fffda2f', 'ability-score-improvement-level-8', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Cleric levels 8, 12, and 16.', '8', '6', '{}'::jsonb, '{}'::jsonb),
  ('600987e1-8e59-516c-a4f3-82da4e6c3704', '34c849dc-dfc7-5f9c-b77f-ad342fffda2f', 'divine-intervention-level-10', 'Divine Intervention', 'You can call on your deity or pantheon to intervene on your behalf. As a Magic action, choose any Cleric spell of level 5 or lower that doesn’t require a Reaction to cast. As part of the same action, you cast that spell without expending a spell slot or needing Material components. You can’t use this feature again until you finish a Long Rest.', '10', '7', '{}'::jsonb, '{}'::jsonb),
  ('6e05bd22-c161-5db0-863a-473cfbfd4de6', '34c849dc-dfc7-5f9c-b77f-ad342fffda2f', 'ability-score-improvement-level-12', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Cleric levels 8, 12, and 16.', '12', '8', '{}'::jsonb, '{}'::jsonb),
  ('34b7bd7b-705f-5862-8fd5-353f6cab8f0f', '34c849dc-dfc7-5f9c-b77f-ad342fffda2f', 'improved-blessed-strikes-level-14', 'Improved Blessed Strikes', 'The option you chose for Blessed Strikes grows more powerful. Divine Strike. The extra damage of your Divine Strike increases to 2d8. Potent Spellcasting. When you cast a Cleric cantrip and deal damage to a creature with it, you can give vitality to yourself or another creature within 60 feet of yourself, granting a number of Temporary Hit Points equal to twice your Wisdom modifier.', '14', '9', '{}'::jsonb, '{}'::jsonb),
  ('aeb7b53b-ccef-54c7-ae86-440de0052cf2', '34c849dc-dfc7-5f9c-b77f-ad342fffda2f', 'ability-score-improvement-level-16', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Cleric levels 8, 12, and 16.', '16', '10', '{}'::jsonb, '{}'::jsonb),
  ('edb31c86-a0ea-5219-862b-c8f1d1a6efc1', '34c849dc-dfc7-5f9c-b77f-ad342fffda2f', 'epic-boon-level-19', 'Epic Boon', 'You gain an Epic Boon feat (see “Feats”) or another feat of your choice for which you qualify. Boon of Fate is recommended.', '19', '11', '{}'::jsonb, '{}'::jsonb),
  ('05ca120b-8dad-5ea2-b178-4b6deeb3ae4c', '34c849dc-dfc7-5f9c-b77f-ad342fffda2f', 'greater-divine-intervention-level-20', 'Greater Divine Intervention', 'You can call on even more powerful divine intervention. When you use your Divine Intervention feature, you can choose Wish when you select a spell. If you do so, you can’t use Divine Intervention again until you finish 2d4 Long Rests.', '20', '12', '{}'::jsonb, '{}'::jsonb),
  ('03988583-f9fc-5cdd-8b54-4da19437962f', 'b449f0f1-b0b6-5b91-b48f-bc85e88ab800', 'spellcasting-level-1', 'Spellcasting', 'You have learned to cast spells through studying the mystical forces of nature. See “Spells” for the rules on spellcasting. The information below details', '1', '0', '{}'::jsonb, '{}'::jsonb),
  ('3c83bec3-5ab1-5a82-9cd3-a71e054b7f10', 'b449f0f1-b0b6-5b91-b48f-bc85e88ab800', 'druidic-level-1', 'Druidic', 'You know Druidic, the secret language of Druids. While learning this ancient tongue, you also unlocked the magic of communicating with animals; you always have the Speak with Animals spell prepared. You can use Druidic to leave hidden messages. You and others who know Druidic automatically spot such a message. Others spot the message’s presence with a successful DC 15 Intelligence (Investigation) check but can’t decipher it without magic.', '1', '1', '{}'::jsonb, '{}'::jsonb),
  ('7c6665e9-1c9d-5216-9130-49233d5afcfc', 'b449f0f1-b0b6-5b91-b48f-bc85e88ab800', 'primal-order-level-1', 'Primal Order', 'You have dedicated yourself to one of the following sacred roles of your choice. Magician. You know one extra cantrip from the Druid spell list. In addition, your mystical connection to nature gives you a bonus to your Intelligence (Arcana or Nature) checks. The bonus equals your Wisdom modifier (minimum bonus of +1). Warden. Trained for battle, you gain proficiency with Martial weapons and training with Medium armor.', '1', '2', '{}'::jsonb, '{}'::jsonb),
  ('3db18400-d321-5479-9910-87abce80e93c', 'b449f0f1-b0b6-5b91-b48f-bc85e88ab800', 'wild-shape-level-2', 'Wild Shape', 'The power of nature allows you to assume the form of an animal. As a Bonus Action, you shape-shift into a Beast form that you have learned for this feature (see “Known Forms” below). You stay in that form for a number of hours equal to half your Druid level or until you use Wild Shape again, have the Incapacitated condition, or die. You can also leave the form early as a Bonus Action. Number of Uses. You can use Wild Shape twice. You regain one expended use when you finish a Short Rest, and you regain all expended uses when you finish a Long Rest. You gain additional uses when you reach certain Druid levels, as shown in the Wild Shape column of the Druid Features table. Known Forms. You know four Beast forms for this feature, chosen from among Beast stat blocks that have a maximum Challenge Rating of 1/4 and that lack a Fly Speed (see “Animals” in “Monsters” for stat block options). The Rat, Riding Horse, Spider , and Wolf are recommended. Whenever you finish a Long Rest, you can replace one of your known forms with another eligible form. When you reach certain Druid levels, your number of known forms and the maximum Challenge Rating for those forms increases, as shown in the Beast Shapes table. In addition, starting at level 8, you can adopt a form that has a Fly Speed. When choosing known forms, you may look in other sources for eligible Beasts if the Game Master permits you to do so. Beast Shapes Druid Level Known Forms Max CR Fly Speed 2 4 1/4 No 4 6 1/2 No 8 8 1 Yes Rules While Shape-Shifted. While in a form, you retain your personality, memories, and ability to speak, and the following rules apply: Temporary Hit Points. When you assume a Wild Shape form, you gain a number of Temporary Hit Points equal to your Druid level. Game Statistics. Your game statistics are replaced by the Beast’s stat block, but you retain your creature type; Hit Points; Hit Point Dice; Intelligence, Wisdom, and Charisma scores; class features; languages; and feats. You also retain your skill and saving throw proficiencies and use your Proficiency Bonus for them, in addition to gaining the proficiencies of the creature. If a skill or saving throw modifier in the Beast’s stat block is higher than yours, use the one in the stat block. No Spellcasting. You can’t cast spells, but shapeshifting doesn’t break your Concentration or otherwise interfere with a spell you’ve already cast. Objects. Your ability to handle objects is determined by the form’s limbs rather than your own. In addition, you choose whether your equipment falls in your space, merges into your new form, or is worn by it. Worn equipment functions as normal, but the GM decides whether it’s practical for the new form to wear a piece of equipment based on the creature’s size and shape. Your equipment doesn’t change size or shape to match the new form, and any equipment that the new form can’t wear must either fall to the ground or merge with the form. Equipment that merges with the form has no effect while you’re in that form.', '2', '3', '{}'::jsonb, '{}'::jsonb),
  ('923ffd8b-01c3-5c0e-89d8-2e8df40b84c6', 'b449f0f1-b0b6-5b91-b48f-bc85e88ab800', 'wild-companion-level-2', 'Wild Companion', 'You can summon a nature spirit that assumes an animal form to aid you. As a Magic action, you can expend a spell slot or a use of Wild Shape to cast the Find Familiar spell without Material components. When you cast the spell in this way, the familiar is Fey and disappears when you finish a Long Rest. Level 3: Druid Subclass You gain a Druid subclass of your choice. The Circle of the Land subclass is detailed after this class’s description. A subclass is a specialization that grants you features at certain Druid levels. For the rest of your career, you gain each of your subclass’s features that are of your Druid level or lower.', '2', '4', '{}'::jsonb, '{}'::jsonb),
  ('3b549816-5375-5721-ab5f-8107347b2653', 'b449f0f1-b0b6-5b91-b48f-bc85e88ab800', 'ability-score-improvement-level-4', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Druid levels 8, 12, and 16.', '4', '5', '{}'::jsonb, '{}'::jsonb),
  ('1bd3889a-0ed0-5651-9b10-c8bed4e27157', 'b449f0f1-b0b6-5b91-b48f-bc85e88ab800', 'wild-resurgence-level-5', 'Wild Resurgence', 'Once on each of your turns, if you have no uses of Wild Shape left, you can give yourself one use by expending a spell slot (no action required). In addition, you can expend one use of Wild Shape (no action required) to give yourself a level 1 spell slot, but you can’t do so again until you finish a Long Rest.', '5', '6', '{}'::jsonb, '{}'::jsonb),
  ('83d75910-8791-5685-824b-2b0388064ccf', 'b449f0f1-b0b6-5b91-b48f-bc85e88ab800', 'elemental-fury-level-7', 'Elemental Fury', 'The might of the elements flows through you. You gain one of the following options of your choice. Potent Spellcasting. Add your Wisdom modifier to the damage you deal with any Druid cantrip. Primal Strike. Once on each of your turns when you hit a creature with an attack roll using a weapon or a Beast form’s attack in Wild Shape, you can cause the target to take an extra 1d8 Cold, Fire, Lightning, or Thunder damage (choose when you hit).', '7', '7', '{}'::jsonb, '{}'::jsonb),
  ('3cb62ac6-60ae-500a-b27d-161edb207077', 'b449f0f1-b0b6-5b91-b48f-bc85e88ab800', 'ability-score-improvement-level-8', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Druid levels 8, 12, and 16.', '8', '8', '{}'::jsonb, '{}'::jsonb),
  ('3254dd1a-a32d-5e1f-ab0b-6ef3817baf27', 'b449f0f1-b0b6-5b91-b48f-bc85e88ab800', 'ability-score-improvement-level-12', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Druid levels 8, 12, and 16.', '12', '9', '{}'::jsonb, '{}'::jsonb),
  ('aa3f58c3-bd72-52a6-8f04-1148352a3750', 'b449f0f1-b0b6-5b91-b48f-bc85e88ab800', 'improved-elemental-fury-level-15', 'Improved Elemental Fury', 'The option you chose for Elemental Fury grows more powerful, as detailed below. Potent Spellcasting. When you cast a Druid cantrip with a range of 10 feet or greater, the spell’s range increases by 300 feet. Primal Strike. The extra damage of your Primal Strike increases to 2d8.', '15', '10', '{}'::jsonb, '{}'::jsonb),
  ('d3384316-0670-5a96-8524-92bd37cd663a', 'b449f0f1-b0b6-5b91-b48f-bc85e88ab800', 'ability-score-improvement-level-16', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Druid levels 8, 12, and 16.', '16', '11', '{}'::jsonb, '{}'::jsonb),
  ('989b4b7d-7264-5b1f-9433-76db1a45e4f0', 'b449f0f1-b0b6-5b91-b48f-bc85e88ab800', 'beast-spells-level-18', 'Beast Spells', 'While using Wild Shape, you can cast spells in Beast form, except for any spell that has a Material component with a cost specified or that consumes its Material component.', '18', '12', '{}'::jsonb, '{}'::jsonb),
  ('d900f041-788a-5dbe-a7cf-77b092dd6500', 'b449f0f1-b0b6-5b91-b48f-bc85e88ab800', 'epic-boon-level-19', 'Epic Boon', 'You gain an Epic Boon feat (see “Feats”) or another feat of your choice for which you qualify. Boon of Dimensional Travel is recommended.', '19', '13', '{}'::jsonb, '{}'::jsonb),
  ('c737d04c-9d3b-55e4-803e-deb838e4bdab', 'b449f0f1-b0b6-5b91-b48f-bc85e88ab800', 'archdruid-level-20', 'Archdruid', 'The vitality of nature constantly blooms within you, granting you the following benefits. Evergreen Wild Shape. Whenever you roll Initiative and have no uses of Wild Shape left, you regain one expended use of it. Nature Magician. You can convert uses of Wild Shape into a spell slot (no action required). Choose a number of your unexpended uses of Wild Shape and convert them into a single spell slot, with each use contributing 2 spell levels. For example, if you convert two uses of Wild Shape, you produce a level 4 spell slot. Once you use this benefit, you can’t do so again until you finish a Long Rest. Longevity. The primal magic that you wield causes you to age more slowly. For every ten years that pass, your body ages only one year.', '20', '14', '{}'::jsonb, '{}'::jsonb),
  ('d6adc8d9-9f72-56ad-b34a-42f5febfe631', '6b143f9f-d5f3-53a8-8719-02a16d3ea716', 'fighting-style-level-1', 'Fighting Style', 'You have honed your martial prowess and gain a Fighting Style feat of your choice (see “Feats”). Defense is recommended. Whenever you gain a Fighter level, you can replace the feat you chose with a different Fighting Style feat.', '1', '0', '{}'::jsonb, '{}'::jsonb),
  ('1d7d7f8e-fc8e-5846-8230-710bef44eed7', '6b143f9f-d5f3-53a8-8719-02a16d3ea716', 'second-wind-level-1', 'Second Wind', 'You have a limited well of physical and mental stamina that you can draw on. As a Bonus Action, you can use it to regain Hit Points equal to 1d10 plus your Fighter level. You can use this feature twice. You regain one expended use when you finish a Short Rest, and you regain all expended uses when you finish a Long Rest. When you reach certain Fighter levels, you gain more uses of this feature, as shown in the Second Wind column of the Fighter Features table.', '1', '1', '{}'::jsonb, '{}'::jsonb),
  ('5ab80ed8-0c61-51ad-86b2-4cb6ccce2ca8', '6b143f9f-d5f3-53a8-8719-02a16d3ea716', 'weapon-mastery-level-1', 'Weapon Mastery', 'Your training with weapons allows you to use the mastery properties of three kinds of Simple or Martial weapons of your choice. Whenever you finish a Long Rest, you can practice weapon drills and change one of those weapon choices. When you reach certain Fighter levels, you gain the ability to use the mastery properties of more kinds of weapons, as shown in the Weapon Mastery column of the Fighter Features table.', '1', '2', '{}'::jsonb, '{}'::jsonb),
  ('d3cfba1f-300a-5a27-8a6a-e1c9e37dfa96', '6b143f9f-d5f3-53a8-8719-02a16d3ea716', 'action-surge-level-2', 'Action Surge', 'You can push yourself beyond your normal limits for a moment. On your turn, you can take one additional action, except the Magic action. Once you use this feature, you can’t do so again until you finish a Short or Long Rest. Starting at level 17, you can use it twice before a rest but only once on a turn.', '2', '3', '{}'::jsonb, '{}'::jsonb),
  ('261e327d-a0b6-5993-9e8c-4e1cdc816206', '6b143f9f-d5f3-53a8-8719-02a16d3ea716', 'tactical-mind-level-2', 'Tactical Mind', 'You have a mind for tactics on and off the battlefield. When you fail an ability check, you can expend a use of your Second Wind to push yourself toward success. Rather than regaining Hit Points, you roll 1d10 and add the number rolled to the ability check, potentially turning it into a success. If the check still fails, this use of Second Wind isn’t expended. Level 3: Fighter Subclass You gain a Fighter subclass of your choice. The Champion subclass is detailed after this class’s description. A subclass is a specialization that grants you features at certain Fighter levels. For the rest of your career, you gain each of your subclass’s features that are of your Fighter level or lower.', '2', '4', '{}'::jsonb, '{}'::jsonb),
  ('4342ec7c-e9b9-5828-a4d2-72bac64b009b', '6b143f9f-d5f3-53a8-8719-02a16d3ea716', 'ability-score-improvement-level-4', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Fighter levels 6, 8, 12, 14, and 16.', '4', '5', '{}'::jsonb, '{}'::jsonb),
  ('288d9175-7dd3-59c8-9446-6408faf4c9e6', '6b143f9f-d5f3-53a8-8719-02a16d3ea716', 'extra-attack-level-5', 'Extra Attack', 'You can attack twice instead of once whenever you take the Attack action on your turn.', '5', '6', '{}'::jsonb, '{}'::jsonb),
  ('b9b3741d-adfd-5a4a-bff3-4dc6d2a9e0b8', '6b143f9f-d5f3-53a8-8719-02a16d3ea716', 'tactical-shift-level-5', 'Tactical Shift', 'Whenever you activate your Second Wind with a Bonus Action, you can move up to half your Speed without provoking Opportunity Attacks.', '5', '7', '{}'::jsonb, '{}'::jsonb),
  ('4b57c967-2281-5561-8e4e-31c0296618e7', '6b143f9f-d5f3-53a8-8719-02a16d3ea716', 'ability-score-improvement-level-6', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Fighter levels 6, 8, 12, 14, and 16.', '6', '8', '{}'::jsonb, '{}'::jsonb),
  ('34cdb2a8-74d1-54cc-baa6-62c1c6bcba7b', '6b143f9f-d5f3-53a8-8719-02a16d3ea716', 'ability-score-improvement-level-8', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Fighter levels 6, 8, 12, 14, and 16.', '8', '9', '{}'::jsonb, '{}'::jsonb),
  ('083d7d7b-3136-5a4c-b6a3-89d329a7b570', '6b143f9f-d5f3-53a8-8719-02a16d3ea716', 'indomitable-level-9', 'Indomitable', 'If you fail a saving throw, you can reroll it with a bonus equal to your Fighter level. You must use the new roll, and you can’t use this feature again until you finish a Long Rest. You can use this feature twice before a Long Rest starting at level 13 and three times before a Long Rest starting at level 17.', '9', '10', '{}'::jsonb, '{}'::jsonb),
  ('054085e7-3be0-58c3-8db9-e458eede8188', '6b143f9f-d5f3-53a8-8719-02a16d3ea716', 'tactical-master-level-9', 'Tactical Master', 'When you attack with a weapon whose mastery property you can use, you can replace that property with the Push, Sap, or Slow property for that attack.', '9', '11', '{}'::jsonb, '{}'::jsonb),
  ('a2ce2989-b083-5d05-865a-9451b9447576', '6b143f9f-d5f3-53a8-8719-02a16d3ea716', 'two-extra-attacks-level-11', 'Two Extra Attacks', 'You can attack three times instead of once whenever you take the Attack action on your turn.', '11', '12', '{}'::jsonb, '{}'::jsonb),
  ('04bd23fc-72e4-5b16-9b43-f6eeb05d35b9', '6b143f9f-d5f3-53a8-8719-02a16d3ea716', 'ability-score-improvement-level-12', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Fighter levels 6, 8, 12, 14, and 16.', '12', '13', '{}'::jsonb, '{}'::jsonb),
  ('0f50724a-53a9-5980-8594-2d12aacf8a60', '6b143f9f-d5f3-53a8-8719-02a16d3ea716', 'studied-attacks-level-13', 'Studied Attacks', 'You study your opponents and learn from each attack you make. If you make an attack roll against a creature and miss, you have Advantage on your next attack roll against that creature before the end of your next turn.', '13', '14', '{}'::jsonb, '{}'::jsonb),
  ('81ec1e96-38c8-5636-922c-73d6f2e9ad18', '6b143f9f-d5f3-53a8-8719-02a16d3ea716', 'ability-score-improvement-level-14', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Fighter levels 6, 8, 12, 14, and 16.', '14', '15', '{}'::jsonb, '{}'::jsonb),
  ('d4b30343-cfd0-5aea-b97b-83e74479ad76', '6b143f9f-d5f3-53a8-8719-02a16d3ea716', 'ability-score-improvement-level-16', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Fighter levels 6, 8, 12, 14, and 16.', '16', '16', '{}'::jsonb, '{}'::jsonb),
  ('f7c0c530-f0d6-51c7-95dc-de9cd7db1589', '6b143f9f-d5f3-53a8-8719-02a16d3ea716', 'epic-boon-level-19', 'Epic Boon', 'You gain an Epic Boon feat (see “Feats”) or another feat of your choice for which you qualify. Boon of Combat Prowess is recommended.', '19', '17', '{}'::jsonb, '{}'::jsonb),
  ('3ffbe62b-0fc7-503a-89f7-4c6bead2c61f', '6b143f9f-d5f3-53a8-8719-02a16d3ea716', 'three-extra-attacks-level-20', 'Three Extra Attacks', 'You can attack four times instead of once whenever you take the Attack action on your turn.', '20', '18', '{}'::jsonb, '{}'::jsonb),
  ('4339ee25-564e-5b6b-a482-349476e76315', 'a7e680c3-1793-5de4-9a33-af770518e180', 'martial-arts-level-1', 'Martial Arts', 'Your practice of martial arts gives you mastery of combat styles that use your Unarmed Strike and Monk weapons, which are the following: • Simple Melee weapons • Martial Melee weapons that have the Light property You gain the following benefits while you are unarmed or wielding only Monk weapons and you aren’t wearing armor or wielding a Shield. Bonus Unarmed Strike. You can make an Unarmed Strike as a Bonus Action. Martial Arts Die. You can roll 1d6 in place of the normal damage of your Unarmed Strike or Monk weapons. This die changes as you gain Monk levels, as shown in the Martial Arts column of the Monk Features table. Dexterous Attacks. You can use your Dexterity modifier instead of your Strength modifier for the attack and damage rolls of your Unarmed Strikes and Monk weapons. In addition, when you use the Grapple or Shove option of your Unarmed Strike, you can use your Dexterity modifier instead of your Strength modifier to determine the save DC.', '1', '0', '{}'::jsonb, '{}'::jsonb),
  ('f70807cd-624a-549e-8db0-0416a9670cac', 'a7e680c3-1793-5de4-9a33-af770518e180', 'unarmored-defense-level-1', 'Unarmored Defense', 'While you aren’t wearing armor or wielding a Shield, your base Armor Class equals 10 plus your Dexterity and Wisdom modifiers.', '1', '1', '{}'::jsonb, '{}'::jsonb),
  ('8afc24bc-4c72-5d95-9510-12bcb09012f6', 'a7e680c3-1793-5de4-9a33-af770518e180', 'monks-focus-level-2', 'Monk’s Focus', 'Your focus and martial training allow you to harness a well of extraordinary energy within yourself. This energy is represented by Focus Points. Your Monk level determines the number of points you have, as shown in the Focus Points column of the Monk Features table. You can expend these points to enhance or fuel certain Monk features. You start knowing three such features: Flurry of Blows, Patient Defense, and Step of the Wind, each of which is detailed below. When you expend a Focus Point, it is unavailable until you finish a Short or Long Rest, at the end of which you regain all your expended points. Some features that use Focus Points require your target to make a saving throw. The save DC equals 8 plus your Wisdom modifier and Proficiency Bonus. Flurry of Blows. You can expend 1 Focus Point to make two Unarmed Strikes as a Bonus Action. Patient Defense. You can take the Disengage action as a Bonus Action. Alternatively, you can', '2', '2', '{}'::jsonb, '{}'::jsonb),
  ('cf80cd5e-5f40-54df-9c0c-b9de9ef66362', 'a7e680c3-1793-5de4-9a33-af770518e180', 'unarmored-movement-level-2', 'Unarmored Movement', 'Your speed increases by 10 feet while you aren’t wearing armor or wielding a Shield. This bonus increases when you reach certain Monk levels, as shown on the Monk Features table.', '2', '3', '{}'::jsonb, '{}'::jsonb),
  ('03219f71-4e04-5053-8b78-c03dfeaa6aec', 'a7e680c3-1793-5de4-9a33-af770518e180', 'uncanny-metabolism-level-2', 'Uncanny Metabolism', 'When you roll Initiative, you can regain all expended Focus Points. When you do so, roll your Martial Arts die, and regain a number of Hit Points equal to your Monk level plus the number rolled. Once you use this feature, you can’t use it again until you finish a Long Rest.', '2', '4', '{}'::jsonb, '{}'::jsonb),
  ('ccce1026-8b30-5276-83c1-be58ca872363', 'a7e680c3-1793-5de4-9a33-af770518e180', 'deflect-attacks-level-3', 'Deflect Attacks', 'When an attack roll hits you and its damage includes Bludgeoning, Piercing, or Slashing damage, you can take a Reaction to reduce the attack’s total damage against you. The reduction equals 1d10 plus your Dexterity modifier and Monk level. If you reduce the damage to 0, you can expend 1 Focus Point to redirect some of the attack’s force. If you do so, choose a creature you can see within 5 feet of yourself if the attack was a melee attack or a creature you can see within 60 feet of yourself that isn’t behind Total Cover if the attack was a ranged attack. That creature must succeed on a Dexterity saving throw or take damage equal to two rolls of your Martial Arts die plus your Dexterity modifier. The damage is the same type dealt by the attack. Level 3: Monk Subclass You gain a Monk subclass of your choice. The Warrior of the Open Hand subclass is detailed after this class’s description. A subclass is a specialization that grants you features at certain Monk levels. For the rest of your career, you gain each of your subclass’s features that are of your Monk level or lower.', '3', '5', '{}'::jsonb, '{}'::jsonb),
  ('1ae3f717-b93d-5325-a35c-a682f8a0369c', 'a7e680c3-1793-5de4-9a33-af770518e180', 'ability-score-improvement-level-4', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Monk levels 8, 12, and 16.', '4', '6', '{}'::jsonb, '{}'::jsonb),
  ('1d40c887-359b-5b11-831b-008bccd7d87f', 'a7e680c3-1793-5de4-9a33-af770518e180', 'slow-fall-level-4', 'Slow Fall', 'You can take a Reaction when you fall to reduce any damage you take from the fall by an amount equal to five times your Monk level.', '4', '7', '{}'::jsonb, '{}'::jsonb),
  ('f4647c30-aca9-5cd2-8206-ab52388508a7', 'a7e680c3-1793-5de4-9a33-af770518e180', 'extra-attack-level-5', 'Extra Attack', 'You can attack twice instead of once whenever you take the Attack action on your turn.', '5', '8', '{}'::jsonb, '{}'::jsonb),
  ('54a47d3b-3a3f-5b02-b952-1d77fb3de51e', 'a7e680c3-1793-5de4-9a33-af770518e180', 'stunning-strike-level-5', 'Stunning Strike', 'Once per turn when you hit a creature with a Monk weapon or an Unarmed Strike, you can expend 1 Focus Point to attempt a stunning strike. The target must make a Constitution saving throw. On a failed save, the target has the Stunned condition until the start of your next turn. On a successful save, the target’s Speed is halved until the start of your next turn, and the next attack roll made against the target before then has Advantage.', '5', '9', '{}'::jsonb, '{}'::jsonb),
  ('dd7aa948-ed4c-542a-9f95-54872866e17a', 'a7e680c3-1793-5de4-9a33-af770518e180', 'empowered-strikes-level-6', 'Empowered Strikes', 'Whenever you deal damage with your Unarmed Strike, it can deal your choice of Force damage or its normal damage type.', '6', '10', '{}'::jsonb, '{}'::jsonb),
  ('c23f7e6d-0d7f-5129-901b-c145c0d98a03', 'a7e680c3-1793-5de4-9a33-af770518e180', 'evasion-level-7', 'Evasion', 'When you’re subjected to an effect that allows you to make a Dexterity saving throw to take only half damage, you instead take no damage if you succeed on the saving throw and only half damage if you fail. You don’t benefit from this feature if you have the Incapacitated condition.', '7', '11', '{}'::jsonb, '{}'::jsonb),
  ('5dd9ae3c-8204-5bdb-8cd8-4db05f2cf8aa', 'a7e680c3-1793-5de4-9a33-af770518e180', 'ability-score-improvement-level-8', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Monk levels 8, 12, and 16.', '8', '12', '{}'::jsonb, '{}'::jsonb),
  ('179cf0df-73c4-5962-942a-0b21be031cf6', 'a7e680c3-1793-5de4-9a33-af770518e180', 'acrobatic-movement-level-9', 'Acrobatic Movement', 'While you aren’t wearing armor or wielding a Shield, you gain the ability to move along vertical surfaces and across liquids on your turn without falling during the movement.', '9', '13', '{}'::jsonb, '{}'::jsonb),
  ('daa047a7-c6b0-5d0d-98ac-58aaec4e92b2', 'a7e680c3-1793-5de4-9a33-af770518e180', 'heightened-focus-level-10', 'Heightened Focus', 'Your Flurry of Blows, Patient Defense, and Step of the Wind gain the following benefits. Flurry of Blows. You can expend 1 Focus Point to use Flurry of Blows and make three Unarmed Strikes with it instead of two. Patient Defense. When you expend a Focus Point to use Patient Defense, you gain a number of Temporary Hit Points equal to two rolls of your Martial Arts die. Step of the Wind. When you expend a Focus Point to use Step of the Wind, you can choose a willing creature within 5 feet of yourself that is Large or smaller. You move the creature with you until the end of your turn. The creature’s movement doesn’t provoke Opportunity Attacks.', '10', '14', '{}'::jsonb, '{}'::jsonb),
  ('503a12ae-8091-586d-a6f5-9ea560e581bb', 'a7e680c3-1793-5de4-9a33-af770518e180', 'self-restoration-level-10', 'Self-Restoration', 'Through sheer force of will, you can remove one of the following conditions from yourself at the end of each of your turns: Charmed, Frightened, or Poisoned. In addition, forgoing food and drink doesn’t give you levels of Exhaustion.', '10', '15', '{}'::jsonb, '{}'::jsonb),
  ('7bcd218f-d394-55e0-80ab-7291ccbb00cb', 'a7e680c3-1793-5de4-9a33-af770518e180', 'ability-score-improvement-level-12', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Monk levels 8, 12, and 16.', '12', '16', '{}'::jsonb, '{}'::jsonb),
  ('0abe98bf-e3e8-5c73-8271-3c8042581edf', 'a7e680c3-1793-5de4-9a33-af770518e180', 'deflect-energy-level-13', 'Deflect Energy', 'You can now use your Deflect Attacks feature against attacks that deal any damage type, not just Bludgeoning, Piercing, or Slashing.', '13', '17', '{}'::jsonb, '{}'::jsonb),
  ('1b515368-0b14-52ba-a7fd-9702a51fc871', 'a7e680c3-1793-5de4-9a33-af770518e180', 'disciplined-survivor-level-14', 'Disciplined Survivor', 'Your physical and mental discipline grant you proficiency in all saving throws. Additionally, whenever you make a saving throw and fail, you can expend 1 Focus Point to reroll it, and you must use the new roll.', '14', '18', '{}'::jsonb, '{}'::jsonb),
  ('fb2c1d8a-37e5-58d2-91f2-5f86a2eb5234', 'a7e680c3-1793-5de4-9a33-af770518e180', 'perfect-focus-level-15', 'Perfect Focus', 'When you roll Initiative and don’t use Uncanny Metabolism, you regain expended Focus Points until you have 4 if you have 3 or fewer.', '15', '19', '{}'::jsonb, '{}'::jsonb),
  ('9f7fa807-6812-5f6b-9a66-5484a0db261a', 'a7e680c3-1793-5de4-9a33-af770518e180', 'ability-score-improvement-level-16', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Monk levels 8, 12, and 16.', '16', '20', '{}'::jsonb, '{}'::jsonb),
  ('042fd3cd-d170-5859-9b9f-550442f3e62f', 'a7e680c3-1793-5de4-9a33-af770518e180', 'superior-defense-level-18', 'Superior Defense', 'At the start of your turn, you can expend 3 Focus Points to bolster yourself against harm for 1 minute or until you have the Incapacitated condition. During that time, you have Resistance to all damage except Force damage.', '18', '21', '{}'::jsonb, '{}'::jsonb),
  ('40955258-6b42-57fe-9dfb-cff7d04021c3', 'a7e680c3-1793-5de4-9a33-af770518e180', 'epic-boon-level-19', 'Epic Boon', 'You gain an Epic Boon feat (see “Feats”) or another feat of your choice for which you qualify. Boon of Irresistible Offense is recommended.', '19', '22', '{}'::jsonb, '{}'::jsonb),
  ('bb11220f-0536-5fa2-a431-e43d2c0f46f5', 'a7e680c3-1793-5de4-9a33-af770518e180', 'body-and-mind-level-20', 'Body and Mind', 'You have developed your body and mind to new heights. Your Dexterity and Wisdom scores increase by 4, to a maximum of 25.', '20', '23', '{}'::jsonb, '{}'::jsonb),
  ('7ee14443-fe50-58e9-b83f-835721d3082a', '785e1ced-5060-5378-81be-8ee97b6ca952', 'lay-on-hands-level-1', 'Lay On Hands', 'Your blessed touch can heal wounds. You have a pool of healing power that replenishes when you finish a Long Rest. With that pool, you can restore a total number of Hit Points equal to five times your Paladin level.', '1', '0', '{}'::jsonb, '{}'::jsonb),
  ('ab47ff68-3ad9-5067-93f8-e7e449a4966f', '785e1ced-5060-5378-81be-8ee97b6ca952', 'spellcasting-level-1', 'Spellcasting', 'You have learned to cast spells through prayer and meditation. See “Spells” for the rules on spellcasting. The information below details how you use those rules with Paladin spells, which appear in the Paladin spell list later in the class’s description. Spell Slots. The Paladin Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you finish a Long Rest. Prepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose two level 1 Paladin spells. Heroism and Searing Smite are recommended. The number of spells on your list increases as you gain Paladin levels, as shown in the Prepared Spells column of the Paladin Features table. Whenever that number increases, choose additional Paladin spells until the number of spells on your list matches the number in the Paladin Features table. The chosen spells must be of a level for which you have spell slots. For example, if you’re a level 5 Paladin, your list of prepared spells can include six Paladin spells of level 1 or 2 in any combination. If another Paladin feature gives you spells that you always have prepared, those spells don’t count against the number of spells you can prepare with this feature, but those spells otherwise count as Paladin spells for you. Changing Your Prepared Spells. Whenever you finish a Long Rest, you can replace one spell on your list with another Paladin spell for which you have spell slots. Spellcasting Ability. Charisma is your spellcasting ability for your Paladin spells. Spellcasting Focus. You can use a Holy Symbol as a Spellcasting Focus for your Paladin spells.', '1', '1', '{}'::jsonb, '{}'::jsonb),
  ('2ce411a1-e2ba-5b5b-b871-f16f38c1644a', '785e1ced-5060-5378-81be-8ee97b6ca952', 'weapon-mastery-level-1', 'Weapon Mastery', 'Your training with weapons allows you to use the mastery properties of two kinds of weapons of your choice with which you have proficiency, such as Longswords and Javelins. Whenever you finish a Long Rest, you can change the kinds of weapons you chose. For example, you could switch to using the mastery properties of Halberds and Flails.', '1', '2', '{}'::jsonb, '{}'::jsonb),
  ('599a162d-e6eb-5b16-82d3-9673b5a0bc70', '785e1ced-5060-5378-81be-8ee97b6ca952', 'fighting-style-level-2', 'Fighting Style', 'You gain a Fighting Style feat of your choice (see “Feats” for feats). Instead of choosing one of those feats, you can choose the option below. Blessed Warrior. You learn two Cleric cantrips of your choice (see the Cleric class’s section for a list of Cleric spells). Guidance and Sacred Flame are recommended. The chosen cantrips count as Paladin spells for you, and Charisma is your spellcasting ability for them. Whenever you gain a Paladin level, you can replace one of these cantrips with another Cleric cantrip.', '2', '3', '{}'::jsonb, '{}'::jsonb),
  ('75e2ceb6-486d-5541-ad9c-4688c3e5adfd', '785e1ced-5060-5378-81be-8ee97b6ca952', 'paladins-smite-level-2', 'Paladin’s Smite', 'You always have the Divine Smite spell prepared. In addition, you can cast it without expending a spell slot, but you must finish a Long Rest before you can cast it in this way again.', '2', '4', '{}'::jsonb, '{}'::jsonb),
  ('44b0c162-3cce-5046-b402-d47536bdcac6', '785e1ced-5060-5378-81be-8ee97b6ca952', 'channel-divinity-level-3', 'Channel Divinity', 'You can channel divine energy directly from the Outer Planes, using it to fuel magical effects. You start with one such effect: Divine Sense, which is described below. Other Paladin features give additional Channel Divinity effect options. Each time you use this class’s Channel Divinity, you choose which effect from this class to create. You can use this class’s Channel Divinity twice. You regain one of its expended uses when you finish a Short Rest, and you regain all expended uses when you finish a Long Rest. You gain an additional use when you reach Paladin level 11. If a Channel Divinity effect requires a saving throw, the DC equals the spell save DC from this class’s Spellcasting feature. Divine Sense. As a Bonus Action, you can open your awareness to detect Celestials, Fiends, and Undead. For the next 10 minutes or until you have the Incapacitated condition, you know the location of any creature of those types within 60 feet of yourself, and you know its creature type. Within the same radius, you also detect the presence of any place or object that has been consecrated or desecrated, as with the Hallow spell. Level 3: Paladin Subclass You gain a Paladin subclass of your choice. The Oath of Devotion subclass is detailed after this class’s description. A subclass is a specialization that grants you features at certain Paladin levels. For the rest of your career, you gain each of your subclass’s features that are of your Paladin level or lower.', '3', '5', '{}'::jsonb, '{}'::jsonb),
  ('d866d117-1d8a-58f8-89c1-3b43ec9991e2', '785e1ced-5060-5378-81be-8ee97b6ca952', 'ability-score-improvement-level-4', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Paladin levels 8, 12, and 16.', '4', '6', '{}'::jsonb, '{}'::jsonb),
  ('60f09780-3048-5f0d-b869-f7c9a0100b9e', '785e1ced-5060-5378-81be-8ee97b6ca952', 'extra-attack-level-5', 'Extra Attack', 'You can attack twice instead of once whenever you take the Attack action on your turn.', '5', '7', '{}'::jsonb, '{}'::jsonb),
  ('6ac7de00-d420-5688-acb3-15c20bae1685', '785e1ced-5060-5378-81be-8ee97b6ca952', 'faithful-steed-level-5', 'Faithful Steed', 'You can call on the aid of an otherworldly steed. You always have the Find Steed spell prepared. You can also cast the spell once without expending a spell slot, and you regain the ability to do so when you finish a Long Rest.', '5', '8', '{}'::jsonb, '{}'::jsonb),
  ('742979b5-3f47-5b7a-bcec-12da5d8a0157', '785e1ced-5060-5378-81be-8ee97b6ca952', 'aura-of-protection-level-6', 'Aura of Protection', 'You radiate a protective, unseeable aura in a 10-foot Emanation that originates from you. The aura is inactive while you have the Incapacitated condition. You and your allies in the aura gain a bonus to saving throws equal to your Charisma modifier (minimum bonus of +1). If another Paladin is present, a creature can benefit from only one Aura of Protection at a time; the creature chooses which aura while in them.', '6', '9', '{}'::jsonb, '{}'::jsonb),
  ('e942d068-f70d-51dc-8d33-9e6c9a2b94ac', '785e1ced-5060-5378-81be-8ee97b6ca952', 'ability-score-improvement-level-8', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Paladin levels 8, 12, and 16.', '8', '10', '{}'::jsonb, '{}'::jsonb),
  ('6d252a5c-e75f-5401-abcb-cec91e336f60', '785e1ced-5060-5378-81be-8ee97b6ca952', 'abjure-foes-level-9', 'Abjure Foes', 'As a Magic action, you can expend one use of this class’s Channel Divinity to overwhelm foes with awe. As you present your Holy Symbol or weapon, you can target a number of creatures equal to your Charisma modifier (minimum of one creature) that you can see within 60 feet of yourself. Each target must succeed on a Wisdom saving throw or have the Frightened condition for 1 minute or until it takes any damage. While Frightened in this way, a target can do only one of the following on its turns: move, take an action, or take a Bonus Action.', '9', '11', '{}'::jsonb, '{}'::jsonb),
  ('bd19d4d6-42ff-52c7-b902-4b9d17ac3b14', '785e1ced-5060-5378-81be-8ee97b6ca952', 'aura-of-courage-level-10', 'Aura of Courage', 'You and your allies have Immunity to the Frightened condition while in your Aura of Protection. If a Frightened ally enters the aura, that condition has no effect on that ally while there.', '10', '12', '{}'::jsonb, '{}'::jsonb),
  ('87d99f5c-e965-579b-95e1-1d8e6bf42b46', '785e1ced-5060-5378-81be-8ee97b6ca952', 'radiant-strikes-level-11', 'Radiant Strikes', 'Your strikes now carry supernatural power. When you hit a target with an attack roll using a Melee weapon or an Unarmed Strike, the target takes an extra 1d8 Radiant damage.', '11', '13', '{}'::jsonb, '{}'::jsonb),
  ('c762b9a9-5d7b-5556-8b86-aed1de9d187e', '785e1ced-5060-5378-81be-8ee97b6ca952', 'ability-score-improvement-level-12', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Paladin levels 8, 12, and 16.', '12', '14', '{}'::jsonb, '{}'::jsonb),
  ('9ff8cca5-5db7-595d-af48-0e14f04e5bcb', '785e1ced-5060-5378-81be-8ee97b6ca952', 'restoring-touch-level-14', 'Restoring Touch', 'When you use Lay On Hands on a creature, you can also remove one or more of the following conditions from the creature: Blinded, Charmed, Deafened, Frightened, Paralyzed, or Stunned. You must expend 5 Hit Points from the healing pool of Lay On Hands for each of these conditions you remove; those points don’t also restore Hit Points to the creature.', '14', '15', '{}'::jsonb, '{}'::jsonb),
  ('784b5d8a-d27f-504f-8a29-a459dd9a618e', '785e1ced-5060-5378-81be-8ee97b6ca952', 'ability-score-improvement-level-16', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Paladin levels 8, 12, and 16.', '16', '16', '{}'::jsonb, '{}'::jsonb),
  ('d038f4f1-ff5a-5ee4-b4f1-f8b597ef8a66', '785e1ced-5060-5378-81be-8ee97b6ca952', 'aura-expansion-level-18', 'Aura Expansion', 'Your Aura of Protection is now a 30-foot Emanation.', '18', '17', '{}'::jsonb, '{}'::jsonb),
  ('4507a7af-e2df-5453-8ec9-1810dcb3f793', '785e1ced-5060-5378-81be-8ee97b6ca952', 'epic-boon-level-19', 'Epic Boon', 'You gain an Epic Boon feat (see “Feats”) or another feat of your choice for which you qualify. Boon of Truesight is recommended.', '19', '18', '{}'::jsonb, '{}'::jsonb),
  ('9370d4ac-f33c-5ccb-8b8f-599746ad5a70', '69774ce3-58ef-5243-8791-73bc57f5d780', 'spellcasting-level-1', 'Spellcasting', 'You have learned to channel the magical essence of nature to cast spells. See “Spells” for the rules on spellcasting. The information below details how you use those rules with Ranger spells, which appear in the Ranger spell list later in the class’s description. Spell Slots. The Ranger Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you finish a Long Rest. Prepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose two level 1 Ranger spells. Cure Wounds and Ensnaring Strike are recommended. The number of spells on your list increases as you gain Ranger levels, as shown in the Prepared Spells column of the Ranger Features table. Whenever that number increases, choose additional Ranger spells until the number of spells on your list matches the number in the Ranger Features table. The chosen spells must be of a level for which you have spell slots. For example, if you’re a level 5 Ranger, your list of prepared spells can include six Ranger spells of level 1 or 2 in any combination. If another Ranger feature gives you spells that you always have prepared, those spells don’t count against the number of spells you can prepare with this feature, but those spells otherwise count as Ranger spells for you. Changing Your Prepared Spells. Whenever you finish a Long Rest, you can replace one spell on your list with another Ranger spell for which you have spell slots. Spellcasting Ability. Wisdom is your spellcasting ability for your Ranger spells. Spellcasting Focus. You can use a Druidic Focus as a Spellcasting Focus for your Ranger spells.', '1', '0', '{}'::jsonb, '{}'::jsonb),
  ('5c30126a-04a4-5c83-a521-5f4c30f47156', '69774ce3-58ef-5243-8791-73bc57f5d780', 'favored-enemy-level-1', 'Favored Enemy', 'You always have the Hunter’s Mark spell prepared. You can cast it twice without expending a spell slot, and you regain all expended uses of this ability when you finish a Long Rest. The number of times you can cast the spell without a spell slot increases when you reach certain Ranger levels, as shown in the Favored Enemy column of the Ranger Features table.', '1', '1', '{}'::jsonb, '{}'::jsonb),
  ('8992f04b-c5da-5580-91b0-552c7da249f5', '69774ce3-58ef-5243-8791-73bc57f5d780', 'weapon-mastery-level-1', 'Weapon Mastery', 'Your training with weapons allows you to use the mastery properties of two kinds of weapons of your', '1', '2', '{}'::jsonb, '{}'::jsonb),
  ('3ff02985-13b6-54a1-88e6-ae808ab7d246', '69774ce3-58ef-5243-8791-73bc57f5d780', 'deft-explorer-level-2', 'Deft Explorer', 'Thanks to your travels, you gain the following benefits. Expertise. Choose one of your skill proficiencies with which you lack Expertise. You gain Expertise in that skill. Languages. You know two languages of your choice from the language tables in “Character Creation.”', '2', '3', '{}'::jsonb, '{}'::jsonb),
  ('fad64d05-ded9-56cb-ae14-c16021abbee1', '69774ce3-58ef-5243-8791-73bc57f5d780', 'fighting-style-level-2', 'Fighting Style', 'You gain a Fighting Style feat of your choice (see “Feats”). Instead of choosing one of those feats, you can choose the option below. Druidic Warrior. You learn two Druid cantrips of your choice (see the Druid class’s section for a list of Druid spells). Guidance and Starry Wisp are recommended. The chosen cantrips count as Ranger spells for you, and Wisdom is your spellcasting ability for them. Whenever you gain a Ranger level, you can replace one of these cantrips with another Druid cantrip. Level 3: Ranger Subclass You gain a Ranger subclass of your choice. The Hunter subclass is detailed after this class’s description. A subclass is a specialization that grants you features at certain Ranger levels. For the rest of your career, you gain each of your subclass’s features that are of your Ranger level or lower.', '2', '4', '{}'::jsonb, '{}'::jsonb),
  ('0d1a0f1d-a421-5bc4-928c-fe772e8725e6', '69774ce3-58ef-5243-8791-73bc57f5d780', 'ability-score-improvement-level-4', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Ranger levels 8, 12, and 16.', '4', '5', '{}'::jsonb, '{}'::jsonb),
  ('82eaba64-0ff9-5ce3-aeff-f8979a952115', '69774ce3-58ef-5243-8791-73bc57f5d780', 'extra-attack-level-5', 'Extra Attack', 'You can attack twice instead of once whenever you take the Attack action on your turn.', '5', '6', '{}'::jsonb, '{}'::jsonb),
  ('b01528e6-585d-5aa2-91d7-2ce942811d6b', '69774ce3-58ef-5243-8791-73bc57f5d780', 'roving-level-6', 'Roving', 'Your Speed increases by 10 feet while you aren’t wearing Heavy armor. You also have a Climb Speed and a Swim Speed equal to your Speed.', '6', '7', '{}'::jsonb, '{}'::jsonb),
  ('7c8b15a7-0d48-51e4-a2ca-aa873ed36e4d', '69774ce3-58ef-5243-8791-73bc57f5d780', 'ability-score-improvement-level-8', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Ranger levels 8, 12, and 16.', '8', '8', '{}'::jsonb, '{}'::jsonb),
  ('6e2b9d45-3748-5d43-ba53-3366e7fe59e5', '69774ce3-58ef-5243-8791-73bc57f5d780', 'expertise-level-9', 'Expertise', 'Choose two of your skill proficiencies with which you lack Expertise. You gain Expertise in those skills.', '9', '9', '{}'::jsonb, '{}'::jsonb),
  ('cd89df68-cd44-50ba-97db-857d02da48f6', '69774ce3-58ef-5243-8791-73bc57f5d780', 'tireless-level-10', 'Tireless', 'Primal forces now help fuel you on your journeys, granting you the following benefits. Temporary Hit Points. As a Magic action, you can give yourself a number of Temporary Hit Points equal to 1d8 plus your Wisdom modifier (minimum of 1). You can use this action a number of times equal to your Wisdom modifier (minimum of once), and you regain all expended uses when you finish a Long Rest. Decrease Exhaustion. Whenever you finish a Short Rest, your Exhaustion level, if any, decreases by 1.', '10', '10', '{}'::jsonb, '{}'::jsonb),
  ('05f6b0d8-d22c-53d5-b942-74dde7590ca7', '69774ce3-58ef-5243-8791-73bc57f5d780', 'ability-score-improvement-level-12', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Ranger levels 8, 12, and 16.', '12', '11', '{}'::jsonb, '{}'::jsonb),
  ('fcd27861-9ae3-5585-8504-6177940b5134', '69774ce3-58ef-5243-8791-73bc57f5d780', 'relentless-hunter-level-13', 'Relentless Hunter', 'Taking damage can’t break your Concentration on Hunter’s Mark.', '13', '12', '{}'::jsonb, '{}'::jsonb),
  ('a9f91dd2-81af-514e-9ea4-eb9ce75dbacb', '69774ce3-58ef-5243-8791-73bc57f5d780', 'natures-veil-level-14', 'Nature’s Veil', 'You invoke spirits of nature to magically hide yourself. As a Bonus Action, you can give yourself the Invisible condition until the end of your next turn. You can use this feature a number of times equal to your Wisdom modifier (minimum of once), and you regain all expended uses when you finish a Long Rest.', '14', '13', '{}'::jsonb, '{}'::jsonb),
  ('82d1f2ba-f8a8-52aa-ac69-540700d125b9', '69774ce3-58ef-5243-8791-73bc57f5d780', 'ability-score-improvement-level-16', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Ranger levels 8, 12, and 16.', '16', '14', '{}'::jsonb, '{}'::jsonb),
  ('04ff9494-3773-5554-b456-c4838bded5d4', '69774ce3-58ef-5243-8791-73bc57f5d780', 'precise-hunter-level-17', 'Precise Hunter', 'You have Advantage on attack rolls against the creature currently marked by your Hunter’s Mark .', '17', '15', '{}'::jsonb, '{}'::jsonb),
  ('31341983-903a-57f7-be10-ca0462b2fe66', '69774ce3-58ef-5243-8791-73bc57f5d780', 'feral-senses-level-18', 'Feral Senses', 'Your connection to the forces of nature grants you Blindsight with a range of 30 feet.', '18', '16', '{}'::jsonb, '{}'::jsonb),
  ('726374ed-2904-59b2-84f0-319112acc31d', '69774ce3-58ef-5243-8791-73bc57f5d780', 'epic-boon-level-19', 'Epic Boon', 'You gain an Epic Boon feat (see “Feats”) or another feat of your choice for which you qualify. Boon of Dimensional Travel is recommended.', '19', '17', '{}'::jsonb, '{}'::jsonb),
  ('1ddda9c3-018f-5be7-9796-2c9d2f0065a3', '69774ce3-58ef-5243-8791-73bc57f5d780', 'foe-slayer-level-20', 'Foe Slayer', 'The damage die of your Hunter’s Mark is a d10 rather than a d6.', '20', '18', '{}'::jsonb, '{}'::jsonb),
  ('ef5f5eea-ecfe-5361-883e-ea43b609c158', 'a9d07b8e-7a78-5e0d-8e09-4fb9fdaa9eed', 'expertise-level-1', 'Expertise', 'You gain Expertise in two of your skill proficiencies of your choice. Sleight of Hand and Stealth are recommended if you have proficiency in them. At Rogue level 6, you gain Expertise in two more of your skill proficiencies of your choice.', '1', '0', '{}'::jsonb, '{}'::jsonb),
  ('cf4a01c1-3c81-59a4-8657-440e0fc3f5f8', 'a9d07b8e-7a78-5e0d-8e09-4fb9fdaa9eed', 'sneak-attack-level-1', 'Sneak Attack', 'You know how to strike subtly and exploit a foe’s distraction. Once per turn, you can deal an extra 1d6 damage to one creature you hit with an attack roll if you have Advantage on the roll and the attack uses a Finesse or a Ranged weapon. The extra damage’s type is the same as the weapon’s type. You don’t need Advantage on the attack roll if at least one of your allies is within 5 feet of the target, the ally doesn’t have the Incapacitated condition, and you don’t have Disadvantage on the attack roll. The extra damage increases as you gain Rogue levels, as shown in the Sneak Attack column of the Rogue Features table.', '1', '1', '{}'::jsonb, '{}'::jsonb),
  ('6ab6230f-2236-5f84-9f67-82bcb62d0e69', 'a9d07b8e-7a78-5e0d-8e09-4fb9fdaa9eed', 'thieves-cant-level-1', 'Thieves’ Cant', 'You picked up various languages in the communities where you plied your roguish talents. You know Thieves’ Cant and one other language of your choice, which you choose from the language tables in “Character Creation.”', '1', '2', '{}'::jsonb, '{}'::jsonb),
  ('aa440d4b-f8f5-5429-81d2-ed5753e79530', 'a9d07b8e-7a78-5e0d-8e09-4fb9fdaa9eed', 'weapon-mastery-level-1', 'Weapon Mastery', 'Your training with weapons allows you to use the mastery properties of two kinds of weapons of your choice with which you have proficiency, such as Daggers and Shortbows. Whenever you finish a Long Rest, you can change the kinds of weapons you chose. For example, you could switch to using the mastery properties of Scimitars and Shortswords.', '1', '3', '{}'::jsonb, '{}'::jsonb),
  ('7c964bbd-9596-5f38-b3ec-80cd2c463ead', 'a9d07b8e-7a78-5e0d-8e09-4fb9fdaa9eed', 'cunning-action-level-2', 'Cunning Action', 'Your quick thinking and agility allow you to move and act quickly. On your turn, you can take one of the following actions as a Bonus Action: Dash, Disengage, or Hide. Level 3: Rogue Subclass You gain a Rogue subclass of your choice. The Thief subclass is detailed after this class’s description. A subclass is a specialization that grants you features at certain Rogue levels. For the rest of your career, you gain each of your subclass’s features that are of your Rogue level or lower.', '2', '4', '{}'::jsonb, '{}'::jsonb),
  ('c134c732-01e2-5a9a-a621-1d96e47c8475', 'a9d07b8e-7a78-5e0d-8e09-4fb9fdaa9eed', 'steady-aim-level-3', 'Steady Aim', 'As a Bonus Action, you give yourself Advantage on your next attack roll on the current turn. You can use this feature only if you haven’t moved during this turn, and after you use it, your Speed is 0 until the end of the current turn.', '3', '5', '{}'::jsonb, '{}'::jsonb),
  ('6b2146e9-0384-56bb-9d7f-fe50cd45383e', 'a9d07b8e-7a78-5e0d-8e09-4fb9fdaa9eed', 'ability-score-improvement-level-4', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Rogue levels 8, 10, 12, and 16.', '4', '6', '{}'::jsonb, '{}'::jsonb),
  ('442ba6ea-6c2d-5d52-9e7a-843078473f87', 'a9d07b8e-7a78-5e0d-8e09-4fb9fdaa9eed', 'cunning-strike-level-5', 'Cunning Strike', 'You’ve developed cunning ways to use your Sneak Attack. When you deal Sneak Attack damage, you can add one of the following Cunning Strike effects. Each effect has a die cost, which is the number of Sneak Attack damage dice you must forgo to add the effect. You remove the die before rolling, and the effect occurs immediately after the attack’s damage is dealt. For example, if you add the Poison effect, remove 1d6 from the Sneak Attack’s damage before rolling. If a Cunning Strike effect requires a saving throw, the DC equals 8 plus your Dexterity modifier and Proficiency Bonus. Poison (Cost: 1d6). You add a toxin to your strike, forcing the target to make a Constitution saving throw. On a failed save, the target has the Poisoned condition for 1 minute. At the end of each of its turns, the Poisoned target repeats the save, ending the effect on itself on a success. To use this effect, you must have a Poisoner’s Kit on your person. Trip (Cost: 1d6). If the target is Large or smaller, it must succeed on a Dexterity saving throw or have the Prone condition. Withdraw (Cost: 1d6). Immediately after the attack, you move up to half your Speed without provoking Opportunity Attacks.', '5', '7', '{}'::jsonb, '{}'::jsonb),
  ('6b56744a-2eb1-5198-8705-7b06ccb6153d', 'a9d07b8e-7a78-5e0d-8e09-4fb9fdaa9eed', 'uncanny-dodge-level-5', 'Uncanny Dodge', 'When an attacker that you can see hits you with an attack roll, you can take a Reaction to halve the attack’s damage against you (round down).', '5', '8', '{}'::jsonb, '{}'::jsonb),
  ('51007010-a4fd-5238-8153-a1c8221d733a', 'a9d07b8e-7a78-5e0d-8e09-4fb9fdaa9eed', 'evasion-level-7', 'Evasion', 'You can nimbly dodge out of the way of certain dangers. When you’re subjected to an effect that allows you to make a Dexterity saving throw to take only half damage, you instead take no damage if you succeed on the saving throw and only half damage if you fail. You can’t use this feature if you have the Incapacitated condition.', '7', '9', '{}'::jsonb, '{}'::jsonb),
  ('2697a7bc-376a-544c-bc4d-c3dc119d7963', 'a9d07b8e-7a78-5e0d-8e09-4fb9fdaa9eed', 'reliable-talent-level-7', 'Reliable Talent', 'Whenever you make an ability check that uses one of your skill or tool proficiencies, you can treat a d20 roll of 9 or lower as a 10.', '7', '10', '{}'::jsonb, '{}'::jsonb),
  ('0a588f4a-e72b-5418-871b-cf470105986d', 'a9d07b8e-7a78-5e0d-8e09-4fb9fdaa9eed', 'ability-score-improvement-level-8', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Rogue levels 8, 10, 12, and 16.', '8', '11', '{}'::jsonb, '{}'::jsonb),
  ('e39b04c7-caa8-5cd0-81f4-76553a5cf507', 'a9d07b8e-7a78-5e0d-8e09-4fb9fdaa9eed', 'improved-cunning-strike-level-11', 'Improved Cunning Strike', 'You can use up to two Cunning Strike effects when you deal Sneak Attack damage, paying the die cost for each effect.', '11', '12', '{}'::jsonb, '{}'::jsonb),
  ('4a741834-c20a-5b9f-ada0-81faa37f0f19', 'a9d07b8e-7a78-5e0d-8e09-4fb9fdaa9eed', 'ability-score-improvement-level-12', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Rogue levels 8, 10, 12, and 16.', '12', '13', '{}'::jsonb, '{}'::jsonb),
  ('d608f766-1131-56d4-9b5e-e926f2f415f6', 'a9d07b8e-7a78-5e0d-8e09-4fb9fdaa9eed', 'devious-strikes-level-14', 'Devious Strikes', 'You’ve practiced new ways to use your Sneak Attack deviously. The following effects are now among your Cunning Strike options. Daze (Cost: 2d6). The target must succeed on a Constitution saving throw, or on its next turn, it can do only one of the following: move or take an action or a Bonus Action. Knock Out (Cost: 6d6). The target must succeed on a Constitution saving throw, or it has the Unconscious condition for 1 minute or until it takes any damage. The Unconscious target repeats the save at the end of each of its turns, ending the effect on itself on a success. Obscure (Cost: 3d6). The target must succeed on a Dexterity saving throw, or it has the Blinded condition until the end of its next turn.', '14', '14', '{}'::jsonb, '{}'::jsonb),
  ('67008b6e-0b7f-5f85-8a0d-dcc8eb85abdc', 'a9d07b8e-7a78-5e0d-8e09-4fb9fdaa9eed', 'slippery-mind-level-15', 'Slippery Mind', 'Your cunning mind is exceptionally difficult to control. You gain proficiency in Wisdom and Charisma saving throws.', '15', '15', '{}'::jsonb, '{}'::jsonb),
  ('91ccb6f5-2ad9-52dc-b891-75303e8ba5cd', 'a9d07b8e-7a78-5e0d-8e09-4fb9fdaa9eed', 'ability-score-improvement-level-16', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Rogue levels 8, 10, 12, and 16.', '16', '16', '{}'::jsonb, '{}'::jsonb),
  ('4818525c-80b6-572d-a73c-e4e18845712c', 'a9d07b8e-7a78-5e0d-8e09-4fb9fdaa9eed', 'elusive-level-18', 'Elusive', 'You’re so evasive that attackers rarely gain the upper hand against you. No attack roll can have Advantage against you unless you have the Incapacitated condition.', '18', '17', '{}'::jsonb, '{}'::jsonb),
  ('7628ef3c-152c-5f7e-87a4-3f8692c41231', 'a9d07b8e-7a78-5e0d-8e09-4fb9fdaa9eed', 'epic-boon-level-19', 'Epic Boon', 'You gain an Epic Boon feat (see “Feats”) or another feat of your choice for which you qualify. Boon of the Night Spirit is recommended.', '19', '18', '{}'::jsonb, '{}'::jsonb),
  ('4fd98a9b-27b7-556b-83e9-c200683831f8', 'a9d07b8e-7a78-5e0d-8e09-4fb9fdaa9eed', 'stroke-of-luck-level-20', 'Stroke of Luck', 'You have a marvelous knack for succeeding when you need to. If you fail a D20 Test, you can turn the roll into a 20. Once you use this feature, you can’t use it again until you finish a Short or Long Rest.', '20', '19', '{}'::jsonb, '{}'::jsonb),
  ('54596270-00ce-5add-88ea-386f8cb13a1f', 'dbf8d73e-f82f-58a7-a36a-2c3a1ddda08d', 'spellcasting-level-1', 'Spellcasting', 'Drawing from your innate magic, you can cast spells. See “Spells” for the rules on spellcasting. The information below details how you use those rules with Sorcerer spells, which appear in the Sorcerer spell list later in the class’s description. Cantrips. You know four Sorcerer cantrips of your choice. Light, Prestidigitation, Shocking Grasp, and Sorcerous Burst are recommended. Whenever you gain a Sorcerer level, you can replace one of your cantrips from this feature with another Sorcerer cantrip of your choice. When you reach Sorcerer levels 4 and 10, you learn another Sorcerer cantrip of your choice, as shown in the Cantrips column of the Sorcerer Features table. Spell Slots. The Sorcerer Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you finish a Long Rest. Prepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose two level 1 Sorcerer spells. Burning Hands and Detect Magic are recommended. The number of spells on your list increases as you gain Sorcerer levels, as shown in the Prepared Spells column of the Sorcerer Features table. Whenever that number increases, choose additional Sorcerer spells until the number of spells on your list matches the number in the Sorcerer Features table. The chosen spells must be of a level for which you have spell slots. For example, if you’re a level 3 Sorcerer, your list of prepared spells can include six Sorcerer spells of level 1 or 2 in any combination. If another Sorcerer feature gives you spells that you always have prepared, those spells don’t count against the number of spells you can prepare with this feature, but those spells otherwise count as Sorcerer spells for you. Changing Your Prepared Spells. Whenever you gain a Sorcerer level, you can replace one spell on your list with another Sorcerer spell for which you have spell slots. Spellcasting Ability. Charisma is your spellcasting ability for your Sorcerer spells. Spellcasting Focus. You can use an Arcane Focus as a Spellcasting Focus for your Sorcerer spells.', '1', '0', '{}'::jsonb, '{}'::jsonb),
  ('8341d1ed-ff10-5d59-b568-54c6e0a5041f', 'dbf8d73e-f82f-58a7-a36a-2c3a1ddda08d', 'innate-sorcery-level-1', 'Innate Sorcery', 'An event in your past left an indelible mark on you, infusing you with simmering magic. As a Bonus Action, you can unleash that magic for 1 minute, during which you gain the following benefits:', '1', '1', '{}'::jsonb, '{}'::jsonb),
  ('d5cc812d-66a2-5c46-b80f-63ab00170d86', 'dbf8d73e-f82f-58a7-a36a-2c3a1ddda08d', 'font-of-magic-level-2', 'Font of Magic', 'You can tap into the wellspring of magic within yourself. This wellspring is represented by Sorcery Points, which allow you to create a variety of magical effects. You have 2 Sorcery Points, and you gain more as you reach higher levels, as shown in the Sorcery Points column of the Sorcerer Features table. You can’t have more Sorcery Points than the number shown in the table for your level. You regain all expended Sorcery Points when you finish a Long Rest. You can use your Sorcery Points to fuel the options below, along with other features, such as Metamagic, that use those points. Converting Spell Slots to Sorcery Points. You can expend a spell slot to gain a number of Sorcery Points equal to the slot’s level (no action required). Creating Spell Slots. As a Bonus Action, you can transform unexpended Sorcery Points into one spell slot. The Creating Spell Slots table shows the cost of creating a spell slot of a given level, and it lists the minimum Sorcerer level you must be to create a slot. You can create a spell slot no higher than level 5. Any spell slot you create with this feature vanishes when you finish a Long Rest. Creating Spell Slots Spell Slot Level Sorcery Point Cost Min. Sorcerer Level 1 2 2 2 3 3 3 5 5 4 6 7 5 7 9', '2', '2', '{}'::jsonb, '{}'::jsonb),
  ('4c0eeea1-6059-5461-bbee-4efd721b6473', 'dbf8d73e-f82f-58a7-a36a-2c3a1ddda08d', 'metamagic-level-2', 'Metamagic', 'Because your magic flows from within, you can alter your spells to suit your needs; you gain two Metamagic options of your choice from “Meta magic Options” later in this class’s description. You use the chosen options to temporarily modify spells you cast. To use an option, you must spend the number of Sorcery Points that it costs. You can use only one Metamagic option on a spell when you cast it unless otherwise noted in one of those options. Whenever you gain a Sorcerer level, you can replace one of your Metamagic options with one you don’t know. You gain two more options at Sorcerer level 10 and two more at Sorcerer level 17. Level 3: Sorcerer Subclass You gain a Sorcerer subclass of your choice. The Draconic Sorcery subclass is detailed after this class’s description. A subclass is a specialization that grants you features at certain Sorcerer levels. For the rest of your career, you gain each of your subclass’s features that are of your Sorcerer level or lower.', '2', '3', '{}'::jsonb, '{}'::jsonb),
  ('c34c4394-d29d-53cb-b068-7fe3510f5c3e', 'dbf8d73e-f82f-58a7-a36a-2c3a1ddda08d', 'ability-score-improvement-level-4', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Sorcerer levels 8, 12, and 16.', '4', '4', '{}'::jsonb, '{}'::jsonb),
  ('6280b509-563a-55e4-ae64-a0e9b8a6f5a2', 'dbf8d73e-f82f-58a7-a36a-2c3a1ddda08d', 'sorcerous-restoration-level-5', 'Sorcerous Restoration', 'When you finish a Short Rest, you can regain expended Sorcery Points, but no more than a number equal to half your Sorcerer level (round down). Once you use this feature, you can’t do so again until you finish a Long Rest.', '5', '5', '{}'::jsonb, '{}'::jsonb),
  ('fa3dc0fd-2d9b-56cd-865f-2a3006165163', 'dbf8d73e-f82f-58a7-a36a-2c3a1ddda08d', 'sorcery-incarnate-level-7', 'Sorcery Incarnate', 'If you have no uses of Innate Sorcery left, you can use it if you spend 2 Sorcery Points when you take the Bonus Action to activate it. In addition, while your Innate Sorcery feature is active, you can use up to two of your Metamagic options on each spell you cast.', '7', '6', '{}'::jsonb, '{}'::jsonb),
  ('ed72a33e-35df-5d12-90bc-619c554abfec', 'dbf8d73e-f82f-58a7-a36a-2c3a1ddda08d', 'ability-score-improvement-level-8', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Sorcerer levels 8, 12, and 16.', '8', '7', '{}'::jsonb, '{}'::jsonb),
  ('002680b6-7dda-511b-9c9d-a5a43551be8a', 'dbf8d73e-f82f-58a7-a36a-2c3a1ddda08d', 'ability-score-improvement-level-12', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Sorcerer levels 8, 12, and 16.', '12', '8', '{}'::jsonb, '{}'::jsonb),
  ('a84c4ac6-c975-5190-a44c-a5f1ca251214', 'dbf8d73e-f82f-58a7-a36a-2c3a1ddda08d', 'ability-score-improvement-level-16', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Sorcerer levels 8, 12, and 16.', '16', '9', '{}'::jsonb, '{}'::jsonb),
  ('111cc70f-a2b8-59fc-a70f-de878c270d63', 'dbf8d73e-f82f-58a7-a36a-2c3a1ddda08d', 'epic-boon-level-19', 'Epic Boon', 'You gain an Epic Boon feat (see “Feats”) or another feat of your choice for which you qualify. Boon of Dimensional Travel is recommended.', '19', '10', '{}'::jsonb, '{}'::jsonb),
  ('f1448248-6ff2-5330-9e3b-31608e5f695f', 'dbf8d73e-f82f-58a7-a36a-2c3a1ddda08d', 'arcane-apotheosis-level-20', 'Arcane Apotheosis', 'While your Innate Sorcery feature is active, you can use one Metamagic option on each of your turns without spending Sorcery Points on it. Metamagic Options The following options are available to your Metamagic feature. The options are presented in alphabetical order. Careful Spell Cost: 1 Sorcery Point When you cast a spell that forces other creatures to make a saving throw, you can protect some of those creatures from the spell’s full force. To do so, spend 1 Sorcery Point and choose a number of those creatures up to your Charisma modifier (minimum of one creature). A chosen creature automatically succeeds on its saving throw against the spell, and it takes no damage if it would normally take half damage on a successful save. Distant Spell Cost: 1 Sorcery Point When you cast a spell that has a range of at least 5 feet, you can spend 1 Sorcery Point to double the spell’s range. Or when you cast a spell that has a range of Touch, you can spend 1 Sorcery Point to make the spell’s range 30 feet. Empowered Spell Cost: 1 Sorcery Point When you roll damage for a spell, you can spend 1 Sorcery Point to reroll a number of the damage dice up to your Charisma modifier (minimum of one), and you must use the new rolls. You can use Empowered Spell even if you’ve already used a different Metamagic option during the casting of the spell. Extended Spell Cost: 1 Sorcery Point When you cast a spell that has a duration of 1 minute or longer, you can spend 1 Sorcery Point to double its duration to a maximum duration of 24 hours. If the affected spell requires Concentration, you have Advantage on any saving throw you make to maintain that Concentration. Heightened Spell Cost: 2 Sorcery Points When you cast a spell that forces a creature to make a saving throw, you can spend 2 Sorcery Points to give one target of the spell Disadvantage on saves against the spell. Quickened Spell Cost: 2 Sorcery Points When you cast a spell that has a casting time of an action, you can spend 2 Sorcery Points to change the casting time to a Bonus Action for this casting. You can’t modify a spell in this way if you’ve already cast a level 1+ spell on the current turn, nor can you cast a level 1+ spell on this turn after modifying a spell in this way. Seeking Spell Cost: 1 Sorcery Point If you make an attack roll for a spell and miss, you can spend 1 Sorcery Point to reroll the d20, and you must use the new roll. You can use Seeking Spell even if you’ve already used a different Metamagic option during the casting of the spell. Subtle Spell Cost: 1 Sorcery Point When you cast a spell, you can spend 1 Sorcery Point to cast it without any Verbal, Somatic, or Material components, except Material components that are consumed by the spell or that have a cost specified in the spell. Transmuted Spell Cost: 1 Sorcery Point When you cast a spell that deals a type of damage from the following list, you can spend 1 Sorcery Point to change that damage type to one of the other listed types: Acid, Cold, Fire, Lightning, Poison, Thunder. Twinned Spell Cost: 1 Sorcery Point When you cast a spell, such as Charm Person , that can be cast with a higher-level spell slot to target an additional creature, you can spend 1 Sorcery Point to increase the spell’s effective level by 1.', '20', '11', '{}'::jsonb, '{}'::jsonb),
  ('25d73f96-1ea2-506b-95a4-e4f647d975a4', 'e5b23717-e6b9-5d80-b72f-fa1814d2b63c', 'eldritch-invocations-level-1', 'Eldritch Invocations', 'You have unearthed Eldritch Invocations, pieces of forbidden knowledge that imbue you with an abiding magical ability or other lessons. You gain one invocation of your choice, such as Pact of the Tome. Invocations are described in the “Eldritch Invocation Options” section later in this class’s description. Prerequisites. If an invocation has a prerequisite, you must meet it to learn that invocation. For example, if an invocation requires you to be a level 5+ Warlock, you can select the invocation once you reach Warlock level 5. Replacing and Gaining Invocations. Whenever you gain a Warlock level, you can replace one of your invocations with another one for which you qualify. You can’t replace an invocation if it’s a prerequisite for another invocation that you have. When you gain certain Warlock levels, you gain more invocations of your choice, as shown in the Invocations column of the Warlock Features table. You can’t pick the same invocation more than once unless its description says otherwise.', '1', '0', '{}'::jsonb, '{}'::jsonb),
  ('b4341d2f-b7f8-5b1a-8d7d-7fc719a5d7f6', 'e5b23717-e6b9-5d80-b72f-fa1814d2b63c', 'pact-magic-level-1', 'Pact Magic', 'Through occult ceremony, you have formed a pact with a mysterious entity to gain magical powers. The entity is a voice in the shadows—its identity unclear—but its boon to you is concrete: the ability to cast spells. See “Spells” for the rules on spellcasting. The information below details how you use those rules with Warlock spells, which appear in the Warlock spell list later in the class’s description. Cantrips. You know two Warlock cantrips of your choice. Eldritch Blast and Prestidigitation are recommended. Whenever you gain a Warlock level, you can replace one of your cantrips from this feature with another Warlock cantrip of your choice. When you reach Warlock levels 4 and 10, you learn another Warlock cantrip of your choice, as shown in the Cantrips column of the Warlock Features table. Spell Slots. The Warlock Features table shows how many spell slots you have to cast your Warlock spells of levels 1–5. The table also shows the level of those slots, all of which are the same level. You regain all expended Pact Magic spell slots when you finish a Short or Long Rest. For example, when you’re a level 5 Warlock, you have two level 3 spell slots. To cast the level 1 spell Charm Person, you must spend one of those slots, and you cast it as a level 3 spell. Prepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose two level 1 Warlock spells. Charm Person and Hex are recommended. The number of spells on your list increases as you gain Warlock levels, as shown in the Prepared Spells column of the Warlock Features table. Whenever that number increases, choose additional Warlock spells until the number of spells on your list matches the number in the table. The chosen spells must be of a level no higher than what’s shown in the table’s Slot Level column for your level. When you reach level 6, for example, you learn a new Warlock spell, which can be of levels 1–3. If another Warlock feature gives you spells that you always have prepared, those spells don’t count', '1', '1', '{}'::jsonb, '{}'::jsonb),
  ('227c6405-df9e-554f-8d68-3eb0f41ff0d9', 'e5b23717-e6b9-5d80-b72f-fa1814d2b63c', 'magical-cunning-level-2', 'Magical Cunning', 'You can perform an esoteric rite for 1 minute. At the end of it, you regain expended Pact Magic spell slots but no more than a number equal to half your maximum (round up). Once you use this feature, you can’t do so again until you finish a Long Rest. Level 3: Warlock Subclass You gain a Warlock subclass of your choice. The Fiend Patron subclass is detailed after this class’s description. A subclass is a specialization that grants you features at certain Warlock levels. For the rest of your career, you gain each of your subclass’s features that are of your Warlock level or lower.', '2', '2', '{}'::jsonb, '{}'::jsonb),
  ('402b9644-413b-519b-9833-e6bde1fbd1d2', 'e5b23717-e6b9-5d80-b72f-fa1814d2b63c', 'ability-score-improvement-level-4', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Warlock levels 8, 12, and 16.', '4', '3', '{}'::jsonb, '{}'::jsonb),
  ('256bbbcc-07eb-5d51-b8c6-bab9e9a52bc1', 'e5b23717-e6b9-5d80-b72f-fa1814d2b63c', 'ability-score-improvement-level-8', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Warlock levels 8, 12, and 16.', '8', '4', '{}'::jsonb, '{}'::jsonb),
  ('d15ccd8d-5745-5ba1-b4b1-a06c3c209187', 'e5b23717-e6b9-5d80-b72f-fa1814d2b63c', 'contact-patron-level-9', 'Contact Patron', 'In the past, you usually contacted your patron through intermediaries. Now you can communicate directly; you always have the Contact Other Plane spell prepared. With this feature, you can cast the spell without expending a spell slot to contact your patron, and you automatically succeed on the spell’s saving throw. Once you cast the spell with this feature, you can’t do so in this way again until you finish a Long Rest.', '9', '5', '{}'::jsonb, '{}'::jsonb),
  ('caca61b2-3d02-597a-8ee3-70f3f1b487cb', 'e5b23717-e6b9-5d80-b72f-fa1814d2b63c', 'mystic-arcanum-level-11', 'Mystic Arcanum', 'Your patron grants you a magical secret called an arcanum. Choose one level 6 Warlock spell as this arcanum. You can cast your arcanum spell once without expending a spell slot, and you must finish a Long Rest before you can cast it in this way again. As shown in the Warlock Features table, you gain another Warlock spell of your choice that can be cast in this way when you reach Warlock levels 13 (level 7 spell), 15 (level 8 spell), and 17 (level 9 spell). You regain all uses of your Mystic Arcanum when you finish a Long Rest. Whenever you gain a Warlock level, you can replace one of your arcanum spells with another Warlock spell of the same level.', '11', '6', '{}'::jsonb, '{}'::jsonb),
  ('894d15b5-3a15-5fd4-9c9f-c2ff95e549f0', 'e5b23717-e6b9-5d80-b72f-fa1814d2b63c', 'ability-score-improvement-level-12', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Warlock levels 8, 12, and 16.', '12', '7', '{}'::jsonb, '{}'::jsonb),
  ('38548372-5502-5272-b582-9d9b829c07f1', 'e5b23717-e6b9-5d80-b72f-fa1814d2b63c', 'ability-score-improvement-level-16', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Warlock levels 8, 12, and 16.', '16', '8', '{}'::jsonb, '{}'::jsonb),
  ('09796667-b79d-5b6a-8062-c7fe6aed2bfa', 'e5b23717-e6b9-5d80-b72f-fa1814d2b63c', 'epic-boon-level-19', 'Epic Boon', 'You gain an Epic Boon feat (see “Feats”) or another feat of your choice for which you qualify. Boon of Fate is recommended.', '19', '9', '{}'::jsonb, '{}'::jsonb),
  ('747ecd39-b676-5249-8ba5-e76ed3f96717', 'e5b23717-e6b9-5d80-b72f-fa1814d2b63c', 'eldritch-master-level-20', 'Eldritch Master', 'When you use your Magical Cunning feature, you regain all your expended Pact Magic spell slots. Eldritch Invocation Options Eldritch Invocation options appear in alphabetical order. Agonizing Blast Prerequisite: Level 2+ Warlock, a Warlock Cantrip That Deals Damage Choose one of your known Warlock cantrips that deals damage. You can add your Charisma modifier to that spell’s damage rolls. Repeatable. You can gain this invocation more than once. Each time you do so, choose a different eligible cantrip. Armor of Shadows You can cast Mage Armor on yourself without expending a spell slot. Ascendant Step Prerequisite: Level 5+ Warlock You can cast Levitate on yourself without expending a spell slot. Devil’s Sight Prerequisite: Level 2+ Warlock You can see normally in Dim Light and Darkness— both magical and nonmagical—within 120 feet of yourself. Devouring Blade Prerequisite: Level 12+ Warlock, Thirsting Blade Invocation The Extra Attack of your Thirsting Blade invocation confers two extra attacks rather than one. Eldritch Mind You have Advantage on Constitution saving throws that you make to maintain Concentration. Eldritch Smite Prerequisite: Level 5+ Warlock, Pact of the Blade Invocation Once per turn when you hit a creature with your pact weapon, you can expend a Pact Magic spell slot to deal an extra 1d8 Force damage to the target, plus another 1d8 per level of the spell slot, and you can give the target the Prone condition if it is Huge or smaller. Eldritch Spear Prerequisite: Level 2+ Warlock, a Warlock Cantrip That Deals Damage Choose one of your known Warlock cantrips that deals damage and has a range of 10+ feet. When you cast that spell, its range increases by a number of feet equal to 30 times your Warlock level. Repeatable. You can gain this invocation more than once. Each time you do so, choose a different eligible cantrip. Fiendish Vigor Prerequisite: Level 2+ Warlock You can cast False Life on yourself without expending a spell slot. When you cast the spell with this feature, you don’t roll the die for the Temporary Hit Points; you automatically get the highest number on the die. Gaze of Two Minds Prerequisite: Level 5+ Warlock You can use a Bonus Action to touch a willing creature and perceive through its senses until the end of your next turn. As long as the creature is on the same plane of existence as you, you can take a Bonus Action on subsequent turns to maintain this connection, extending the duration until the end of your next turn. The connection ends if you don’t maintain it in this way. While perceiving through the other creature’s senses, you benefit from any special senses possessed by that creature, and you can cast spells as if you were in your space or the other creature’s space if the two of you are within 60 feet of each other. Gift of the Depths Prerequisite: Level 5+ Warlock You can breathe underwater, and you gain a Swim Speed equal to your Speed. You can also cast Water Breathing once without expending a spell slot. You regain the ability to cast it in this way again when you finish a Long Rest. Gift of the Protectors Prerequisite: Level 9+ Warlock, Pact of the Tome Invocation A new page appears in your Book of Shadows when you conjure it. With your permission, a creature can take an action to write its name on that page, which can contain a number of names equal to your Charisma modifier (minimum of one name). When any creature whose name is on the page is reduced to 0 Hit Points but not killed outright, the creature magically drops to 1 Hit Point instead. Once this magic is triggered, no creature can benefit from it until you finish a Long Rest. As a Magic action, you can erase a name on the page by touching it. Investment of the Chain Master Prerequisite: Level 5+ Warlock, Pact of the Chain Invocation When you cast Find Familiar, you infuse the summoned familiar with a measure of your eldritch power, granting the creature the following benefits. Aerial or Aquatic. The familiar gains either a Fly Speed or a Swim Speed (your choice) of 40 feet. Quick Attack. As a Bonus Action, you can command the familiar to take the Attack action. Necrotic or Radiant Damage. Whenever the familiar deals Bludgeoning, Piercing, or Slashing damage, you can make it deal Necrotic or Radiant damage instead. Your Save DC. If the familiar forces a creature to make a saving throw, it uses your spell save DC. Resistance. When the familiar takes damage, you can take a Reaction to grant it Resistance against that damage. Lessons of the First Ones Prerequisite: Level 2+ Warlock You have received knowledge from an elder entity of the multiverse, allowing you to gain one Origin feat of your choice (see “Feats”). Repeatable. You can gain this invocation more than once. Each time you do so, choose a different Origin feat. Lifedrinker Prerequisite: Level 9+ Warlock, Pact of the Blade Invocation Once per turn when you hit a creature with your pact weapon, you can deal an extra 1d6 Necrotic, Psychic, or Radiant damage (your choice) to the creature, and you can expend one of your Hit Point Dice to roll it and regain a number of Hit Points equal to the roll plus your Constitution modifier (minimum of 1 Hit Point). Mask of Many Faces Prerequisite: Level 2+ Warlock You can cast Disguise Self without expending a spell slot. Master of Myriad Forms Prerequisite: Level 5+ Warlock You can cast Alter Self without expending a spell slot. Misty Visions Prerequisite: Level 2+ Warlock You can cast Silent Image without expending a spell slot. One with Shadows Prerequisite: Level 5+ Warlock While you’re in an area of Dim Light or Darkness, you can cast Invisibility on yourself without expending a spell slot. Otherworldly Leap Prerequisite: Level 2+ Warlock You can cast Jump on yourself without expending a spell slot. Pact of the Blade As a Bonus Action, you can conjure a pact weapon in your hand—a Simple or Martial Melee weapon of your choice with which you bond—or create a bond with a magic weapon you touch; you can’t bond with a magic weapon if someone else is attuned to it or another Warlock is bonded with it. Until the bond ends, you have proficiency with the weapon, and you can use it as a Spellcasting Focus. Whenever you attack with the bonded weapon, you can use your Charisma modifier for the attack and damage rolls instead of using Strength or Dexterity; and you can cause the weapon to deal Necrotic, Psychic, or Radiant damage or its normal damage type. Your bond with the weapon ends if you use this feature’s Bonus Action again, if the weapon is more than 5 feet away from you for 1 minute or more, or if you die. A conjured weapon disappears when the bond ends. Pact of the Chain You learn the Find Familiar spell and can cast it as a Magic action without expending a spell slot. When you cast the spell, you choose one of the normal forms for your familiar or one of the following special forms: Imp, Pseudodragon, Quasit, Skeleton, Sphinx of Wonder, Sprite, or Venomous Snake (see “Monsters” for the familiar’s stat block). Additionally, when you take the Attack action, you can forgo one of your own attacks to allow your familiar to make one attack of its own with its Reaction. Pact of the Tome Stitching together strands of shadow, you conjure forth a book in your hand at the end of a Short or Long Rest. This Book of Shadows (you determine its appearance) contains eldritch magic that only you can access, granting you the benefits below. The book disappears if you conjure another book with this feature or if you die. Cantrips and Rituals. When the book appears, choose three cantrips, and choose two level 1 spells that have the Ritual tag. The spells can be from any class’s spell list, and they must be spells you don’t already have prepared. While the book is on your person, you have the chosen spells prepared, and they function as Warlock spells for you. Spellcasting Focus. You can use the book as a Spellcasting Focus. Repelling Blast Prerequisite: Level 2+ Warlock, a Warlock Cantrip That Deals Damage via an Attack Roll Choose one of your known Warlock cantrips that requires an attack roll. When you hit a Large or smaller creature with that cantrip, you can push the creature up to 10 feet straight away from you. Repeatable. You can gain this invocation more than once. Each time you do so, choose a different eligible cantrip. Thirsting Blade Prerequisite: Level 5+ Warlock, Pact of the Blade Invocation You gain the Extra Attack feature for your pact weapon only. With that feature, you can attack twice with the weapon instead of once when you take the Attack action on your turn. Visions of Distant Realms Prerequisite: Level 9+ Warlock You can cast Arcane Eye without expending a spell slot. Whispers of the Grave Prerequisite: Level 7+ Warlock You can cast Speak with Dead without expending a spell slot. Witch Sight Prerequisite: Level 15+ Warlock You have Truesight with a range of 30 feet.', '20', '10', '{}'::jsonb, '{}'::jsonb),
  ('814e7ecc-59b2-532e-a54f-40570295bccd', 'b5122a8b-bc17-5619-ac14-00e1b6306dbd', 'spellcasting-level-1', 'Spellcasting', 'As a student of arcane magic, you have learned to cast spells. See “Spells” for the rules on spellcasting. The information below details how you use those rules with Wizard spells, which appear in the Wizard spell list later in the class’s description. Cantrips. You know three Wizard cantrips of your choice. Light, Mage Hand, and Ray of Frost are recommended. Whenever you finish a Long Rest, you can replace one of your cantrips from this feature with another Wizard cantrip of your choice.', '1', '0', '{}'::jsonb, '{}'::jsonb),
  ('6cc9b6cc-2df5-571a-8773-fa6623308c53', 'b5122a8b-bc17-5619-ac14-00e1b6306dbd', 'ritual-adept-level-1', 'Ritual Adept', 'You can cast any spell as a Ritual if that spell has the Ritual tag and the spell is in your spellbook. You needn’t have the spell prepared, but you must read from the book to cast a spell in this way.', '1', '1', '{}'::jsonb, '{}'::jsonb),
  ('771316f1-de87-54b5-a27a-5b825d14f9a2', 'b5122a8b-bc17-5619-ac14-00e1b6306dbd', 'arcane-recovery-level-1', 'Arcane Recovery', 'You can regain some of your magical energy by studying your spellbook. When you finish a Short Rest, you can choose expended spell slots to recover. The spell slots can have a combined level equal to no more than half your Wizard level (round up), and none of the slots can be level 6 or higher. For example, if you’re a level 4 Wizard, you can recover up to two levels’ worth of spell slots, regaining either one level 2 spell slot or two level 1 spell slots. Once you use this feature, you can’t do so again until you finish a Long Rest.', '1', '2', '{}'::jsonb, '{}'::jsonb),
  ('178c2092-968f-5f8f-8a45-cb10b963fe0f', 'b5122a8b-bc17-5619-ac14-00e1b6306dbd', 'scholar-level-2', 'Scholar', 'While studying magic, you also specialized in another field of study. Choose one of the following skills in which you have proficiency: Arcana, History, Investigation, Medicine, Nature, or Religion. You have Expertise in the chosen skill. Level 3: Wizard Subclass You gain a Wizard subclass of your choice. The Evoker subclass is detailed after this class’s description. A subclass is a specialization that grants you features at certain Wizard levels. For the rest of your career, you gain each of your subclass’s features that are of your Wizard level or lower.', '2', '3', '{}'::jsonb, '{}'::jsonb),
  ('4e260c0e-f492-57ce-aafd-65c2218ce78b', 'b5122a8b-bc17-5619-ac14-00e1b6306dbd', 'ability-score-improvement-level-4', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Wizard levels 8, 12, and 16.', '4', '4', '{}'::jsonb, '{}'::jsonb),
  ('db064b5e-61da-57d5-8916-c0b6e0a8ae7c', 'b5122a8b-bc17-5619-ac14-00e1b6306dbd', 'memorize-spell-level-5', 'Memorize Spell', 'Whenever you finish a Short Rest, you can study your spellbook and replace one of the level 1+ Wizard spells you have prepared for your Spellcasting feature with another level 1+ spell from the book.', '5', '5', '{}'::jsonb, '{}'::jsonb),
  ('ddd0a4da-7bbf-553e-92de-fe90fbd069f0', 'b5122a8b-bc17-5619-ac14-00e1b6306dbd', 'ability-score-improvement-level-8', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Wizard levels 8, 12, and 16.', '8', '6', '{}'::jsonb, '{}'::jsonb),
  ('0bea20af-c75c-5930-ae48-cb4aa407e644', 'b5122a8b-bc17-5619-ac14-00e1b6306dbd', 'ability-score-improvement-level-12', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Wizard levels 8, 12, and 16.', '12', '7', '{}'::jsonb, '{}'::jsonb),
  ('99f1f19f-d7e3-5265-8381-3333fc2d1bb2', 'b5122a8b-bc17-5619-ac14-00e1b6306dbd', 'ability-score-improvement-level-16', 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see “Feats”) or another feat of your choice for which you qualify. You gain this feature again at Wizard levels 8, 12, and 16.', '16', '8', '{}'::jsonb, '{}'::jsonb),
  ('e91eb5f0-a719-5a00-9b78-09fe44b9e889', 'b5122a8b-bc17-5619-ac14-00e1b6306dbd', 'spell-mastery-level-18', 'Spell Mastery', 'You have achieved such mastery over certain spells that you can cast them at will. Choose a level 1 and a level 2 spell in your spellbook that have a casting time of an action. You always have those spells prepared, and you can cast them at their lowest level without expending a spell slot. To cast either spell at a higher level, you must expend a spell slot. Whenever you finish a Long Rest, you can study your spellbook and replace one of those spells with an eligible spell of the same level from the book.', '18', '9', '{}'::jsonb, '{}'::jsonb),
  ('424d2f0d-bccd-5766-b422-74d878961bf6', 'b5122a8b-bc17-5619-ac14-00e1b6306dbd', 'epic-boon-level-19', 'Epic Boon', 'You gain an Epic Boon feat (see “Feats”) or another feat of your choice for which you qualify. Boon of Spell Recall is recommended.', '19', '10', '{}'::jsonb, '{}'::jsonb),
  ('aad4eb9b-db0a-5bd4-ba7a-308011ba6ffc', 'b5122a8b-bc17-5619-ac14-00e1b6306dbd', 'signature-spells-level-20', 'Signature Spells', 'Choose two level 3 spells in your spellbook as your signature spells. You always have these spells prepared, and you can cast each of them once at level 3 without expending a spell slot. When you do so, you can’t cast them in this way again until you finish a Short or Long Rest. To cast either spell at a higher level, you must expend a spell slot.', '20', '11', '{}'::jsonb, '{}'::jsonb)
insert into public.subclass_features (id, subclass_id, slug, name, description, level, sort_order, choices, prerequisites) values
  ('f9c4c225-d6db-56bd-8c2e-139b80ec64db', '2ef3e11a-b954-5660-8f98-88e778757ac0', 'frenzy-level-3', 'Frenzy', 'If you use Reckless Attack while your Rage is active, you deal extra damage to the first target you hit on your turn with a Strength-based attack. To determine the extra damage, roll a number of d6s equal to your Rage Damage bonus, and add them together. The damage has the same type as the weapon or Unarmed Strike used for the attack.', '3', '0', '{}'::jsonb, '{}'::jsonb),
  ('ac66a91b-0615-55f2-ab23-77bd69282406', '2ef3e11a-b954-5660-8f98-88e778757ac0', 'mindless-rage-level-6', 'Mindless Rage', 'You have Immunity to the Charmed and Frightened conditions while your Rage is active. If you’re Charmed or Frightened when you enter your Rage, the condition ends on you.', '6', '1', '{}'::jsonb, '{}'::jsonb),
  ('04e4aa9d-7e75-5b38-a3b4-517d57b3701a', '2ef3e11a-b954-5660-8f98-88e778757ac0', 'retaliation-level-10', 'Retaliation', 'When you take damage from a creature that is within 5 feet of you, you can take a Reaction to make one melee attack against that creature, using a weapon or an Unarmed Strike.', '10', '2', '{}'::jsonb, '{}'::jsonb),
  ('4353e757-1f88-5fb8-8124-5a0ca460db5c', '2ef3e11a-b954-5660-8f98-88e778757ac0', 'intimidating-presence-level-14', 'Intimidating Presence', 'As a Bonus Action, you can strike terror into others with your menacing presence and primal power. When you do so, each creature of your choice in a 30-foot Emanation originating from you must make a Wisdom saving throw (DC 8 plus your Strength modifier and Proficiency Bonus). On a failed save, a creature has the Frightened condition for 1 minute. At the end of each of the Frightened creature’s turns, the creature repeats the save, ending the effect on itself on a success. Once you use this feature, you can’t use it again until you finish a Long Rest unless you expend a use of your Rage (no action required) to restore your use of it. Bard', '14', '3', '{}'::jsonb, '{}'::jsonb),
  ('fdfcd498-f7ac-5226-b211-e198c85abc9a', '2652e01b-5e7d-540d-a513-3af113b0632b', 'bonus-proficiencies-level-3', 'Bonus Proficiencies', 'You gain proficiency with three skills of your choice.', '3', '0', '{}'::jsonb, '{}'::jsonb),
  ('5ad5b743-8101-5b40-a250-43f10e25244a', '2652e01b-5e7d-540d-a513-3af113b0632b', 'cutting-words-level-3', 'Cutting Words', 'You learn to use your wit to supernaturally distract, confuse, and otherwise sap the confidence and competence of others. When a creature that you can see within 60 feet of yourself makes a damage roll or succeeds on an ability check or attack roll, you can take a Reaction to expend one use of your Bardic Inspiration; roll your Bardic Inspiration die, and subtract the number rolled from the creature’s roll, reducing the damage or potentially turning the success into a failure.', '3', '1', '{}'::jsonb, '{}'::jsonb),
  ('7c288714-ba20-566d-a655-37126e6438f3', '2652e01b-5e7d-540d-a513-3af113b0632b', 'magical-discoveries-level-6', 'Magical Discoveries', 'You learn two spells of your choice. These spells can come from the Cleric, Druid, or Wizard spell list or any combination thereof (see a class’s section for its spell list). A spell you choose must be a cantrip or a spell for which you have spell slots, as shown in the Bard Features table. You always have the chosen spells prepared, and whenever you gain a Bard level, you can replace one of the spells with another spell that meets these requirements.', '6', '2', '{}'::jsonb, '{}'::jsonb),
  ('15d67a72-abcc-54aa-8cf9-8dc2b55d7883', '2652e01b-5e7d-540d-a513-3af113b0632b', 'peerless-skill-level-14', 'Peerless Skill', 'When you make an ability check or attack roll and fail, you can expend one use of Bardic Inspiration; roll the Bardic Inspiration die, and add the number rolled to the d20, potentially turning a failure into a success. On a failure, the Bardic Inspiration isn’t expended. Cleric', '14', '3', '{}'::jsonb, '{}'::jsonb),
  ('3d112911-d1e6-5f80-a42b-2c88590a909d', 'c14a2ee6-343c-5812-bda8-63e0b30d72d5', 'disciple-of-life-level-3', 'Disciple of Life', 'When a spell you cast with a spell slot restores Hit Points to a creature, that creature regains additional Hit Points on the turn you cast the spell. The additional Hit Points equal 2 plus the spell slot’s level.', '3', '0', '{}'::jsonb, '{}'::jsonb),
  ('9e1233ad-7fe1-5244-8815-d8cbbb40e631', 'c14a2ee6-343c-5812-bda8-63e0b30d72d5', 'life-domain-spells-level-3', 'Life Domain Spells', 'Your connection to this divine domain ensures you always have certain spells ready. When you reach a Cleric level specified in the Life Domain Spells table, you thereafter always have the listed spells prepared. Life Domain Spells Cleric Level Prepared Spells 3 Aid, Bless, Cure Wounds, Lesser Restoration 5 Mass Healing Word, Revivify 7 Aura of Life, Death Ward 9 Greater Restoration , Mass Cure Wounds', '3', '1', '{}'::jsonb, '{}'::jsonb),
  ('ff70d268-c945-579a-a614-f8b3c2a6c4d9', 'c14a2ee6-343c-5812-bda8-63e0b30d72d5', 'preserve-life-level-3', 'Preserve Life', 'As a Magic action, you present your Holy Symbol and expend a use of your Channel Divinity to evoke healing energy that can restore a number of Hit Points equal to five times your Cleric level. Choose Bloodied creatures within 30 feet of yourself (which can include you), and divide those Hit Points among them. This feature can restore a creature to no more than half its Hit Point maximum.', '3', '2', '{}'::jsonb, '{}'::jsonb),
  ('2ff089cc-226e-5f6a-a37b-e86565a122e9', 'c14a2ee6-343c-5812-bda8-63e0b30d72d5', 'blessed-healer-level-6', 'Blessed Healer', 'The healing spells you cast on others heal you as well. Immediately after you cast a spell with a spell slot that restores Hit Points to one or more creatures other than yourself, you regain Hit Points equal to 2 plus the spell slot’s level.', '6', '3', '{}'::jsonb, '{}'::jsonb),
  ('9c761b59-3ec7-5d1a-818e-bc1d7505ab74', 'c14a2ee6-343c-5812-bda8-63e0b30d72d5', 'supreme-healing-level-17', 'Supreme Healing', 'When you would normally roll one or more dice to restore Hit Points to a creature with a spell or Channel Divinity, don’t roll those dice for the healing; instead use the highest number possible for each die. For example, instead of restoring 2d6 Hit Points to a creature with a spell, you restore 12. Druid', '17', '4', '{}'::jsonb, '{}'::jsonb),
  ('afb4cd31-f9d5-528b-86a1-d363c0fd741e', '4064c082-baf5-597d-8f3f-5fa3ced994aa', 'circle-of-the-land-spells-level-3', 'Circle of the Land Spells', 'Whenever you finish a Long Rest, choose one type of land: arid, polar, temperate, or tropical. Consult the table below that corresponds to the chosen type; you have the spells listed for your Druid level and lower prepared. Arid Land Druid Level Circle Spells 3 Blur, Burning Hands, Fire Bolt 5 Fireball 7 Blight 9 Wall of Stone Polar Land Druid Level Circle Spells 3 Fog Cloud, Hold Person, Ray of Frost 5 Sleet Storm 7 Ice Storm 9 Cone of Cold Temperate Land Druid Level Circle Spells 3 Misty Step, Shocking Grasp , Sleep 5 Lightning Bolt 7 Freedom of Movement 9 Tree Stride Tropical Land Druid Level Circle Spells 3 Acid Splash, Ray of Sickness , Web 5 Stinking Cloud 7 Polymorph 9 Insect Plague', '3', '0', '{}'::jsonb, '{}'::jsonb),
  ('e817d0e7-0626-54df-b1a7-8d616a45d435', '4064c082-baf5-597d-8f3f-5fa3ced994aa', 'lands-aid-level-3', 'Land’s Aid', 'As a Magic action, you can expend a use of your Wild Shape and choose a point within 60 feet of yourself. Vitality-giving flowers and life-draining thorns appear for a moment in a 10-foot-radius Sphere centered on that point. Each creature of your choice in the Sphere must make a Constitution saving throw against your spell save DC, taking 2d6 Necrotic damage on a failed save or half as much damage on a successful one. One creature of your choice in that area regains 2d6 Hit Points. The damage and healing increase by 1d6 when you reach Druid levels 10 (3d6) and 14 (4d6).', '3', '1', '{}'::jsonb, '{}'::jsonb),
  ('c2c57ae7-0254-50a8-a521-5220890db857', '4064c082-baf5-597d-8f3f-5fa3ced994aa', 'natural-recovery-level-6', 'Natural Recovery', 'You can cast one of the level 1+ spells that you have prepared from your Circle Spells feature without expending a spell slot, and you must finish a Long Rest before you do so again. In addition, when you finish a Short Rest, you can choose expended spell slots to recover. The spell slots can have a combined level that is equal to or less than half your Druid level (round up), and none of them can be level 6+. For example, if you’re a level 6 Druid, you can recover up to three levels’ worth of spell slots. You can recover a level 3 spell slot, a level 2 and a level 1 spell slot, or three level 1 spell slots. Once you recover spell slots with this feature, you can’t do so again until you finish a Long Rest.', '6', '2', '{}'::jsonb, '{}'::jsonb),
  ('4a9f2098-6ae7-5a52-b31b-f4c7ce4896f9', '4064c082-baf5-597d-8f3f-5fa3ced994aa', 'natures-ward-level-10', 'Nature’s Ward', 'You are immune to the Poisoned condition, and you have Resistance to a damage type associated with your current land choice in the Circle Spells feature, as shown in the Nature’s Ward table. Nature’s Ward Land Type Resistance Arid Fire Polar Cold Land Type Resistance Temperate Lightning Tropical Poison', '10', '3', '{}'::jsonb, '{}'::jsonb),
  ('70b92534-f694-591d-9892-849e35c5d04e', '4064c082-baf5-597d-8f3f-5fa3ced994aa', 'natures-sanctuary-level-14', 'Nature’s Sanctuary', 'As a Magic action, you can expend a use of your Wild Shape and cause spectral trees and vines to appear in a 15-foot Cube on the ground within 120 feet of yourself. They last there for 1 minute or until you have the Incapacitated condition or die. You and your allies have Half Cover while in that area, and your allies gain the current Resistance of your Nature’s Ward while there. As a Bonus Action, you can move the Cube up to 60 feet to ground within 120 feet of yourself. Fighter', '14', '4', '{}'::jsonb, '{}'::jsonb),
  ('bdb6858c-2404-528f-8a8b-ca4ce9b0fdd3', '4e77cc18-7c2c-5465-bf5d-f5c30dd5939d', 'improved-critical-level-3', 'Improved Critical', 'Your attack rolls with weapons and Unarmed Strikes can score a Critical Hit on a roll of 19 or 20 on the d20.', '3', '0', '{}'::jsonb, '{}'::jsonb),
  ('b105c231-36f7-5c89-8f0b-d9744f62985e', '4e77cc18-7c2c-5465-bf5d-f5c30dd5939d', 'remarkable-athlete-level-3', 'Remarkable Athlete', 'Thanks to your athleticism, you have Advantage on Initiative rolls and Strength (Athletics) checks. In addition, immediately after you score a Critical Hit, you can move up to half your Speed without provoking Opportunity Attacks.', '3', '1', '{}'::jsonb, '{}'::jsonb),
  ('ac926345-5e77-5876-ad31-0a9600788b07', '4e77cc18-7c2c-5465-bf5d-f5c30dd5939d', 'additional-fighting-style-level-7', 'Additional Fighting Style', 'You gain another Fighting Style feat of your choice.', '7', '2', '{}'::jsonb, '{}'::jsonb),
  ('60d182cf-7c5c-5ca4-8ebf-8b7402a715ce', '4e77cc18-7c2c-5465-bf5d-f5c30dd5939d', 'heroic-warrior-level-10', 'Heroic Warrior', 'The thrill of battle drives you toward victory. During combat, you can give yourself Heroic Inspiration whenever you start your turn without it.', '10', '3', '{}'::jsonb, '{}'::jsonb),
  ('8076167b-0a4f-580f-9ed2-c2c1f15c32ba', '4e77cc18-7c2c-5465-bf5d-f5c30dd5939d', 'superior-critical-level-15', 'Superior Critical', 'Your attack rolls with weapons and Unarmed Strikes can now score a Critical Hit on a roll of 18–20 on the d20.', '15', '4', '{}'::jsonb, '{}'::jsonb),
  ('284ddcc5-ba1a-59ba-94f7-f18b81ad462d', '4e77cc18-7c2c-5465-bf5d-f5c30dd5939d', 'survivor-level-18', 'Survivor', 'You attain the pinnacle of resilience in battle, giving you these benefits. Defy Death. You have Advantage on Death Saving Throws. Moreover, when you roll 18–20 on a Death Saving Throw, you gain the benefit of rolling a 20 on it. Heroic Rally. At the start of each of your turns, you regain Hit Points equal to 5 plus your Constitution modifier if you are Bloodied and have at least 1 Hit Point. Monk', '18', '5', '{}'::jsonb, '{}'::jsonb),
  ('bd4c3157-d1c0-57bf-856c-cd780713022e', 'ec0244d7-3b5b-55f9-ab3b-11f9a16ce608', 'open-hand-technique-level-3', 'Open Hand Technique', 'Whenever you hit a creature with an attack granted by your Flurry of Blows, you can impose one of the following effects on that target. Addle. The target can’t make Opportunity Attacks until the start of its next turn. Push. The target must succeed on a Strength saving throw or be pushed up to 15 feet away from you. Topple. The target must succeed on a Dexterity saving throw or have the Prone condition.', '3', '0', '{}'::jsonb, '{}'::jsonb),
  ('4b739448-98a0-58f7-a6d7-5a94f0d09f94', 'ec0244d7-3b5b-55f9-ab3b-11f9a16ce608', 'wholeness-of-body-level-6', 'Wholeness of Body', 'You gain the ability to heal yourself. As a Bonus Action, you can roll your Martial Arts die. You regain a number of Hit Points equal to the number rolled plus your Wisdom modifier (minimum of 1 Hit Point regained). You can use this feature a number of times equal to your Wisdom modifier (minimum of once), and you regain all expended uses when you finish a Long Rest.', '6', '1', '{}'::jsonb, '{}'::jsonb),
  ('2fe2864b-a7a9-5306-a408-5bee4898e18d', 'ec0244d7-3b5b-55f9-ab3b-11f9a16ce608', 'fleet-step-level-11', 'Fleet Step', 'When you take a Bonus Action other than Step of the Wind, you can also use Step of the Wind immediately after that Bonus Action.', '11', '2', '{}'::jsonb, '{}'::jsonb),
  ('5641f735-44c1-57af-90bf-90f24ffe6972', 'ec0244d7-3b5b-55f9-ab3b-11f9a16ce608', 'quivering-palm-level-17', 'Quivering Palm', 'You gain the ability to set up lethal vibrations in someone’s body. When you hit a creature with an Unarmed Strike, you can expend 4 Focus Points to start these imperceptible vibrations, which last for a number of days equal to your Monk level. The vibrations are harmless unless you take an action to end them. Alternatively, when you take the Attack action on your turn, you can forgo one of the attacks to end the vibrations. To end them, you and the target must be on the same plane of existence. When you end them, the target must make a Constitution saving throw, taking 10d12 Force damage on a failed save or half as much damage on a successful one. You can have only one creature under the effect of this feature at a time. You can end the vibrations harmlessly (no action required). Paladin', '17', '3', '{}'::jsonb, '{}'::jsonb),
  ('f69c30ec-79bd-5846-a3fb-f9d32732618f', '705c71cf-9a8b-5e5e-8d4a-0b561faecd3c', 'oath-of-devotion-spells-level-3', 'Oath of Devotion Spells', 'The magic of your oath ensures you always have certain spells ready; when you reach a Paladin level specified in the Oath of Devotion Spells table, you thereafter always have the listed spells prepared. Oath of Devotion Spells Paladin Level Spells 3 Protection from Evil and Good , Shield of Faith 5 Aid, Zone of Truth 9 Beacon of Hope, Dispel Magic 13 Freedom of Movement , Guardian of Faith 17 Commune, Flame Strike', '3', '0', '{}'::jsonb, '{}'::jsonb),
  ('2946ba20-3663-52c7-a8ad-03768c3c0ee1', '705c71cf-9a8b-5e5e-8d4a-0b561faecd3c', 'sacred-weapon-level-3', 'Sacred Weapon', 'When you take the Attack action, you can expend one use of your Channel Divinity to imbue one Melee weapon that you are holding with positive energy. For 10 minutes or until you use this feature again, you add your Charisma modifier to attack rolls you make with that weapon (minimum bonus of +1), and each time you hit with it, you cause it to deal its normal damage type or Radiant damage. The weapon also emits Bright Light in a 20-foot radius and Dim Light 20 feet beyond that. You can end this effect early (no action required). This effect also ends if you aren’t carrying the weapon.', '3', '1', '{}'::jsonb, '{}'::jsonb),
  ('f5d7df9d-c252-5559-8e6c-708f65ba91de', '705c71cf-9a8b-5e5e-8d4a-0b561faecd3c', 'aura-of-devotion-level-7', 'Aura of Devotion', 'You and your allies have Immunity to the Charmed condition while in your Aura of Protection. If a Charmed ally enters the aura, that condition has no effect on that ally while there.', '7', '2', '{}'::jsonb, '{}'::jsonb),
  ('ad463bc2-c58e-5271-9c8a-6b10e53d4449', '705c71cf-9a8b-5e5e-8d4a-0b561faecd3c', 'smite-of-protection-level-15', 'Smite of Protection', 'Your magical smite now radiates protective energy. Whenever you cast Divine Smite , you and your allies have Half Cover while in your Aura of Protection. The aura has this benefit until the start of your next turn.', '15', '3', '{}'::jsonb, '{}'::jsonb),
  ('80e48d23-6ece-5f82-81df-da46d1048674', '705c71cf-9a8b-5e5e-8d4a-0b561faecd3c', 'holy-nimbus-level-20', 'Holy Nimbus', 'As a Bonus Action, you can imbue your Aura of Protection with holy power, granting the benefits below for 10 minutes or until you end them (no action required). Once you use this feature, you can’t use it again until you finish a Long Rest. You can also restore your use of it by expending a level 5 spell slot (no action required). Holy Ward. You have Advantage on any saving throw you are forced to make by a Fiend or an Undead. Radiant Damage. Whenever an enemy starts its turn in the aura, that creature takes Radiant damage equal to your Charisma modifier plus your Proficiency Bonus. Sunlight. The aura is filled with Bright Light that is sunlight. Ranger', '20', '4', '{}'::jsonb, '{}'::jsonb),
  ('3c55d83b-697c-556c-b6bf-c4908b0b7a53', 'e0d69daf-a13f-5c45-a3cd-3c0cdb236a00', 'hunters-lore-level-3', 'Hunter’s Lore', 'You can call on the forces of nature to reveal certain strengths and weaknesses of your prey. While a creature is marked by your Hunter’s Mark , you know whether that creature has any Immunities, Resistances, or Vulnerabilities, and if the creature has any, you know what they are.', '3', '0', '{}'::jsonb, '{}'::jsonb),
  ('bad9b5a2-4d79-5156-9a01-9c3af0567952', 'e0d69daf-a13f-5c45-a3cd-3c0cdb236a00', 'hunters-prey-level-3', 'Hunter’s Prey', 'You gain one of the following feature options of your choice. Whenever you finish a Short or Long Rest, you can replace the chosen option with the other one. Colossus Slayer. Your tenacity can wear down even the most resilient foes. When you hit a creature with a weapon, the weapon deals an extra 1d8 damage to the target if it’s missing any of its Hit Points. You can deal this extra damage only once per turn. Horde Breaker. Once on each of your turns when you make an attack with a weapon, you can make another attack with the same weapon against a different creature that is within 5 feet of the original target, that is within the weapon’s range, and that you haven’t attacked this turn.', '3', '1', '{}'::jsonb, '{}'::jsonb),
  ('7320fc08-9f9b-59ef-b23c-f6eb37e4a9ad', 'e0d69daf-a13f-5c45-a3cd-3c0cdb236a00', 'defensive-tactics-level-7', 'Defensive Tactics', 'You gain one of the following feature options of your choice. Whenever you finish a Short or Long Rest, you can replace the chosen option with the other one. Escape the Horde. Opportunity Attacks have Disadvantage against you. Multiattack Defense. When a creature hits you with an attack roll, that creature has Disadvantage on all other attack rolls against you this turn.', '7', '2', '{}'::jsonb, '{}'::jsonb),
  ('080db1fc-e8d1-516f-9f83-9ec42c2ef10c', 'e0d69daf-a13f-5c45-a3cd-3c0cdb236a00', 'superior-hunters-prey-level-11', 'Superior Hunter’s Prey', 'Once per turn when you deal damage to a creature marked by your Hunter’s Mark, you can also deal that spell’s extra damage to a different creature that you can see within 30 feet of the first creature.', '11', '3', '{}'::jsonb, '{}'::jsonb),
  ('e85d7dce-2777-5d35-800b-cda76361a565', 'e0d69daf-a13f-5c45-a3cd-3c0cdb236a00', 'superior-hunters-defense-level-15', 'Superior Hunter’s Defense', 'When you take damage, you can take a Reaction to give yourself Resistance to that damage and any other damage of the same type until the end of the current turn. Rogue', '15', '4', '{}'::jsonb, '{}'::jsonb),
  ('5ac0daed-1431-5dfe-aad9-85286c51bbc1', 'f6c6f0ca-7e54-5cc9-a2c4-c3a90dda6b11', 'fast-hands-level-3', 'Fast Hands', 'As a Bonus Action, you can do one of the following. Sleight of Hand. Make a Dexterity (Sleight of Hand) check to pick a lock or disarm a trap with Thieves’ Tools or to pick a pocket. Use an Object. Take the Utilize action, or take the Magic action to use a magic item that requires that action.', '3', '0', '{}'::jsonb, '{}'::jsonb),
  ('4913ba63-37c8-5226-8e65-cf010b263076', 'f6c6f0ca-7e54-5cc9-a2c4-c3a90dda6b11', 'second-story-work-level-3', 'Second-Story Work', 'You’ve trained to get into especially hard-to-reach places, granting you these benefits. Climber. You gain a Climb Speed equal to your Speed. Jumper. You can determine your jump distance using your Dexterity rather than your Strength.', '3', '1', '{}'::jsonb, '{}'::jsonb),
  ('2997134b-813f-58ec-a468-fd903b529864', 'f6c6f0ca-7e54-5cc9-a2c4-c3a90dda6b11', 'supreme-sneak-level-9', 'Supreme Sneak', 'You gain the following Cunning Strike option. Stealth Attack (Cost: 1d6). If you have the Hide action’s Invisible condition, this attack doesn’t end that condition on you if you end the turn behind Three-Quarters Cover or Total Cover.', '9', '2', '{}'::jsonb, '{}'::jsonb),
  ('dafc45da-e3b4-5a2c-ba5d-f3a00618096e', 'f6c6f0ca-7e54-5cc9-a2c4-c3a90dda6b11', 'use-magic-device-level-13', 'Use Magic Device', 'You’ve learned how to maximize use of magic items, granting you the following benefits. Attunement. You can attune to up to four magic items at once. Charges. Whenever you use a magic item property that expends charges, roll 1d6. On a roll of 6, you use the property without expending the charges. Scrolls. You can use any Spell Scroll, using Intelligence as your spellcasting ability for the spell. If the spell is a cantrip or a level 1 spell, you can cast it reliably. If the scroll contains a higher-level spell, you must first succeed on an Intelligence (Arcana) check (DC 10 plus the spell’s level). On a successful check, you cast the spell from the scroll. On a failed check, the scroll disintegrates.', '13', '3', '{}'::jsonb, '{}'::jsonb),
  ('82142564-141b-5a1f-9528-3d4526867621', 'f6c6f0ca-7e54-5cc9-a2c4-c3a90dda6b11', 'thiefs-reflexes-level-17', 'Thief’s Reflexes', 'You are adept at laying ambushes and quickly escaping danger. You can take two turns during the first round of any combat. You take your first turn at your normal Initiative and your second turn at your Initiative minus 10. Sorcerer', '17', '4', '{}'::jsonb, '{}'::jsonb),
  ('72983ff0-45f6-5176-b1be-7a6b7fa02c59', '30728cae-bb3a-5f5e-9ecc-0e75d8998d33', 'draconic-resilience-level-3', 'Draconic Resilience', 'The magic in your body manifests physical traits of your draconic gift. Your Hit Point maximum increases by 3, and it increases by 1 whenever you gain another Sorcerer level. Parts of you are also covered by dragon-like scales. While you aren’t wearing armor, your base Armor Class equals 10 plus your Dexterity and Charisma modifiers.', '3', '0', '{}'::jsonb, '{}'::jsonb),
  ('bea25671-0dfc-505d-9889-658609dbf91d', '30728cae-bb3a-5f5e-9ecc-0e75d8998d33', 'draconic-spells-level-3', 'Draconic Spells', 'When you reach a Sorcerer level specified in the Draconic Spells table, you thereafter always have the listed spells prepared. Draconic Spells Sorcerer Level Spells 3 Alter Self, Chromatic Orb, Command, Dragon’s Breath 5 Fear, Fly 7 Arcane Eye, Charm Monster 9 Legend Lore, Summon Dragon', '3', '1', '{}'::jsonb, '{}'::jsonb),
  ('72d7dfc8-0be1-5b4f-ab45-9272fb499e58', '30728cae-bb3a-5f5e-9ecc-0e75d8998d33', 'elemental-affinity-level-6', 'Elemental Affinity', 'Your draconic magic has an affinity with a damage type associated with dragons. Choose one of those types: Acid, Cold, Fire, Lightning, or Poison. You have Resistance to that damage type, and when you cast a spell that deals damage of that type, you can add your Charisma modifier to one damage roll of that spell.', '6', '2', '{}'::jsonb, '{}'::jsonb),
  ('d36e35c3-aded-519c-8b3b-01b1ba7c4573', '30728cae-bb3a-5f5e-9ecc-0e75d8998d33', 'dragon-wings-level-14', 'Dragon Wings', 'As a Bonus Action, you can cause draconic wings to appear on your back. The wings last for 1 hour or until you dismiss them (no action required). For the duration, you have a Fly Speed of 60 feet. Once you use this feature, you can’t use it again until you finish a Long Rest unless you spend 3 Sorcery Points (no action required) to restore your use of it.', '14', '3', '{}'::jsonb, '{}'::jsonb),
  ('f8468b57-a3b5-53d8-b43c-9ffec6e84ca8', '30728cae-bb3a-5f5e-9ecc-0e75d8998d33', 'dragon-companion-level-18', 'Dragon Companion', 'You can cast Summon Dragon without a Material component. You can also cast it once without a spell slot, and you regain the ability to cast it in this way when you finish a Long Rest. Whenever you start casting the spell, you can modify it so that it doesn’t require Concentration. If you do so, the spell’s duration becomes 1 minute for that casting. Warlock', '18', '4', '{}'::jsonb, '{}'::jsonb),
  ('7d06016a-58e3-5c4a-8f9f-c5facdd0a45e', '2549fc10-701e-500d-8548-45e6e3c6af21', 'dark-ones-blessing-level-3', 'Dark One’s Blessing', 'When you reduce an enemy to 0 Hit Points, you gain Temporary Hit Points equal to your Charisma modifier plus your Warlock level (minimum of 1 Temporary Hit Point). You also gain this benefit if someone else reduces an enemy within 10 feet of you to 0 Hit Points.', '3', '0', '{}'::jsonb, '{}'::jsonb),
  ('0fece238-3532-5286-9308-f95c826ac86e', '2549fc10-701e-500d-8548-45e6e3c6af21', 'fiend-spells-level-3', 'Fiend Spells', 'The magic of your patron ensures you always have certain spells ready; when you reach a Warlock level specified in the Fiend Spells table, you thereafter always have the listed spells prepared. Fiend Spells Warlock Level Spells 3 Burning Hands, Command, Scorching Ray, Suggestion 5 Fireball, Stinking Cloud 7 Fire Shield, Wall of Fire 9 Geas, Insect Plague', '3', '1', '{}'::jsonb, '{}'::jsonb),
  ('1308da02-db39-5caf-b33b-01f6a2da85e4', '2549fc10-701e-500d-8548-45e6e3c6af21', 'dark-ones-own-luck-level-6', 'Dark One’s Own Luck', 'You can call on your fiendish patron to alter fate in your favor. When you make an ability check or a saving throw, you can use this feature to add 1d10 to your roll. You can do so after seeing the roll but before any of the roll’s effects occur. You can use this feature a number of times equal to your Charisma modifier (minimum of once), but you can use it no more than once per roll. You regain all expended uses when you finish a Long Rest.', '6', '2', '{}'::jsonb, '{}'::jsonb),
  ('ca5b8d37-1887-5b00-89dc-726fec961379', '2549fc10-701e-500d-8548-45e6e3c6af21', 'fiendish-resilience-level-10', 'Fiendish Resilience', 'Choose one damage type, other than Force, whenever you finish a Short or Long Rest. You have Resistance to that damage type until you choose a different one with this feature.', '10', '3', '{}'::jsonb, '{}'::jsonb),
  ('aebbadba-8eb5-5d18-9040-453c9036df45', '2549fc10-701e-500d-8548-45e6e3c6af21', 'hurl-through-hell-level-14', 'Hurl Through Hell', 'Once per turn when you hit a creature with an attack roll, you can try to instantly transport the target through the Lower Planes. The target must succeed on a Charisma saving throw against your spell save DC, or the target disappears and hurtles through a nightmare landscape. The target takes 8d10 Psychic damage if it isn’t a Fiend, and it has the Incapacitated condition until the end of your next turn, when it returns to the space it previously occupied or the nearest unoccupied space. Once you use this feature, you can’t use it again until you finish a Long Rest unless you expend a Pact Magic spell slot (no action required) to restore your use of it. Wizard', '14', '4', '{}'::jsonb, '{}'::jsonb),
  ('a98442d1-cfe6-58db-9db9-81af6e603676', '80fa2ec1-660b-5ad1-a105-950c676858c4', 'evocation-savant-level-3', 'Evocation Savant', 'Choose two Wizard spells from the Evocation school, each of which must be no higher than level 2, and add them to your spellbook for free. In addition, whenever you gain access to a new level of spell slots in this class, you can add one Wizard spell from the Evocation school to your spellbook for free. The chosen spell must be of a level for which you have spell slots.', '3', '0', '{}'::jsonb, '{}'::jsonb),
  ('27100d8e-9bdf-5703-ba97-3d39823b8869', '80fa2ec1-660b-5ad1-a105-950c676858c4', 'potent-cantrip-level-3', 'Potent Cantrip', 'Your damaging cantrips affect even creatures that avoid the brunt of the effect. When you cast a cantrip at a creature and you miss with the attack roll or the target succeeds on a saving throw against the cantrip, the target takes half the cantrip’s damage (if any) but suffers no additional effect from the cantrip.', '3', '1', '{}'::jsonb, '{}'::jsonb),
  ('b98e96ba-8b05-5522-b344-c5a973d7105f', '80fa2ec1-660b-5ad1-a105-950c676858c4', 'sculpt-spells-level-6', 'Sculpt Spells', 'You can create pockets of relative safety within the effects of your evocations. When you cast an Evocation spell that affects other creatures that you can see, you can choose a number of them equal to 1 plus the spell’s level. The chosen creatures automatically succeed on their saving throws against the spell, and they take no damage if they would normally take half damage on a successful save.', '6', '2', '{}'::jsonb, '{}'::jsonb),
  ('24064f92-808e-56da-bdb6-0c7be2cb72ce', '80fa2ec1-660b-5ad1-a105-950c676858c4', 'empowered-evocation-level-10', 'Empowered Evocation', 'Whenever you cast a Wizard spell from the Evocation school, you can add your Intelligence modifier to one damage roll of that spell.', '10', '3', '{}'::jsonb, '{}'::jsonb),
  ('871eab2c-948e-5d24-b736-b030b4dd2999', '80fa2ec1-660b-5ad1-a105-950c676858c4', 'overchannel-level-14', 'Overchannel', 'You can increase the power of your spells. When you cast a Wizard spell with a spell slot of levels 1–5 that deals damage, you can deal maximum damage with that spell on the turn you cast it. The first time you do so, you suffer no adverse effect. If you use this feature again before you finish a Long Rest, you take 2d12 Necrotic damage for each level of the spell slot immediately after you cast it. This damage ignores Resistance and Immunity. Each time you use this feature again before finishing a Long Rest, the Necrotic damage per spell level increases by 1d12.', '14', '4', '{}'::jsonb, '{}'::jsonb)
