  ('7fa631a1-7396-5186-8e8f-6223c7251922', '1a16065b-6561-5d69-93dd-d5450c2d94c7', '13', '{"proficiency_bonus":5,"features":["Improved Brutal Strike"]}'::jsonb),
  ('f768eedc-9fbb-5682-bd49-e8f528093f2a', '1a16065b-6561-5d69-93dd-d5450c2d94c7', '14', '{"proficiency_bonus":5,"features":[]}'::jsonb),
