  ('fce8a0c0-a166-5390-9c4b-2ff536ef9054', '1a16065b-6561-5d69-93dd-d5450c2d94c7', '16', '{"proficiency_bonus":5,"features":["Ability Score Improvement"]}'::jsonb),
