on conflict (id) do update set slug=excluded.slug, name=excluded.name, edition=excluded.edition, source=excluded.source, description=excluded.description, status=excluded.status;

on conflict (id) do update set ruleset_id=excluded.ruleset_id, slug=excluded.slug, name=excluded.name, description=excluded.description, hit_die=excluded.hit_die, primary_abilities=excluded.primary_abilities, saving_throw_proficiencies=excluded.saving_throw_proficiencies, proficiencies=excluded.proficiencies, starting_equipment=excluded.starting_equipment, status=excluded.status;

on conflict (id) do update set class_id=excluded.class_id, slug=excluded.slug, name=excluded.name, description=excluded.description, unlock_level=excluded.unlock_level, status=excluded.status;

on conflict (id) do update set class_id=excluded.class_id, slug=excluded.slug, name=excluded.name, description=excluded.description, level=excluded.level, sort_order=excluded.sort_order, choices=excluded.choices, prerequisites=excluded.prerequisites;

on conflict (id) do update set subclass_id=excluded.subclass_id, slug=excluded.slug, name=excluded.name, description=excluded.description, level=excluded.level, sort_order=excluded.sort_order, choices=excluded.choices, prerequisites=excluded.prerequisites;

on conflict (class_id, level) do update set data=excluded.data;
